const STORE='purchase_demo_v1';
const seed={vendors:[{id:1,name:'Alpha Office Supplies',contact:'Ahmed Khan',phone:'0300-1111111',email:'sales@alpha.test',category:'Office Supplies',status:'Active'},{id:2,name:'Tech Source Pakistan',contact:'Sara Ali',phone:'0301-2222222',email:'sales@techsource.test',category:'IT Equipment',status:'Active'},{id:3,name:'Prime Industrial Traders',contact:'Usman Raza',phone:'0302-3333333',email:'info@primeindustrial.test',category:'Industrial',status:'Active'}],products:[{id:1,name:'A4 Paper Box',sku:'PAP-A4',category:'Stationery',unit:'Box',rate:4200},{id:2,name:'Wireless Keyboard',sku:'IT-KB01',category:'IT Equipment',unit:'Each',rate:3500},{id:3,name:'Office Chair',sku:'FUR-CH01',category:'Furniture',unit:'Each',rate:18500}],requests:[{id:1001,requestNo:'PR-2026-001',requester:'Admin User',department:'Administration',date:'2026-09-01',requiredDate:'2026-09-10',status:'Pending Approval',justification:'Office stationery and equipment required for the administration department.',lineItems:[{productId:1,productName:'A4 Paper Box',description:'80 GSM A4 copy paper',quantity:2,rate:4200,unit:'Box',total:8400},{productId:2,productName:'Wireless Keyboard',description:'USB wireless keyboard',quantity:1,rate:3500,unit:'Each',total:3500},{productId:3,productName:'Office Chair',description:'Ergonomic office chair',quantity:1,rate:13800,unit:'Each',total:13800}],items:3,total:25700}],rfqs:[],quotations:[],orders:[],receipts:[],invoices:[],payments:[],comparisons:[]};
function db(){let x=localStorage.getItem(STORE);if(!x){const fresh=structuredClone(seed);fresh.users=[{id:1,name:'Admin User',email:'admin@purchase.local',password:'admin123',role:'Admin',active:true},{id:2,name:'Procurement Manager',email:'manager@purchase.local',password:'manager123',role:'Procurement Manager',active:true},{id:3,name:'Finance User',email:'finance@purchase.local',password:'finance123',role:'Finance',active:true}];fresh.roles=defaultRoles();localStorage.setItem(STORE,JSON.stringify(fresh));return fresh}const data=JSON.parse(x);if(!Array.isArray(data.comparisons))data.comparisons=[];if(!Array.isArray(data.activities))data.activities=[];data.activities=data.activities.filter(a=>a.action!=='Viewed');if(!Array.isArray(data.users))data.users=[];if(!data.users.length)data.users=[{id:1,name:'Admin User',email:'admin@purchase.local',password:'admin123',role:'Admin',active:true}];if(!data.roles)data.roles=defaultRoles();Object.keys(data.roles||{}).forEach(role=>{data.roles[role].activities=true});localStorage.setItem(STORE,JSON.stringify(data));return data}function defaultRoles(){return {Admin:{dashboard:true,requests:true,rfqs:true,quotations:true,comparison:true,orders:true,receipts:true,invoices:true,payments:true,vendors:true,products:true,reports:true,users:true,activities:true},'Procurement Manager':{dashboard:true,requests:true,rfqs:true,quotations:true,comparison:true,orders:true,receipts:true,invoices:false,payments:false,vendors:true,products:true,reports:true,users:false,activities:true},Requester:{dashboard:true,requests:true,rfqs:false,quotations:false,comparison:false,orders:false,receipts:false,invoices:false,payments:false,vendors:false,products:true,reports:false,users:false,activities:true},Finance:{dashboard:true,requests:false,rfqs:false,quotations:false,comparison:false,orders:false,receipts:true,invoices:true,payments:true,vendors:true,products:false,reports:true,users:false,activities:true},Viewer:{dashboard:true,requests:true,rfqs:true,quotations:true,comparison:true,orders:true,receipts:true,invoices:true,payments:true,vendors:true,products:true,reports:true,users:false,activities:true}}}function currentUser(){try{return JSON.parse(sessionStorage.getItem('purchase_user')||'null')}catch(e){return null}}function can(id){const u=currentUser(),x=db();return !!(u&&u.role&&x.roles&&x.roles[u.role]&&x.roles[u.role][id])}function guard(id){need();if(id&&!can(id)){toast('You do not have permission to access this module');setTimeout(()=>location.href='dashboard.html',500);return false}return true}
function recordActivity(x,action,module,details='',entity=''){
  x.activities=x.activities||[];
  const u=currentUser()||{name:'System',email:'system',role:'System'};
  x.activities.unshift({id:Date.now()+Math.random(),userId:u.id||null,userName:u.name||'System',userEmail:u.email||'',role:u.role||'',action,module,details,entity,createdAt:new Date().toISOString()});
  if(x.activities.length>2000)x.activities=x.activities.slice(0,2000);
}
function logActivity(action,module,details='',entity=''){const x=db();recordActivity(x,action,module,details,entity);save(x)}
function save(x){localStorage.setItem(STORE,JSON.stringify(x))} function esc(x=''){return String(x).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))} function toast(m){const t=document.getElementById('toast')||document.body.appendChild(Object.assign(document.createElement('div'),{id:'toast'}));t.className='toast show';t.textContent=m;setTimeout(()=>t.classList.remove('show'),2500)}
function layout(active,title,sub,body){document.body.innerHTML=`<div class="app"><aside class="sidebar" id="side"><div class="side-brand"><img src="assets/logo.png"></div><div class="sidebar-scroll"><div class="nav-title">PURCHASING</div>${can('dashboard')?nav('dashboard','Dashboard','ti-layout-dashboard',active):''}${can('requests')?nav('requests','Purchase Requests','ti-file-invoice',active):''}${can('rfqs')?nav('rfqs','RFQs','ti-file-description',active):''}${can('quotations')?nav('quotations','Vendor Quotations','ti-file-dollar',active):''}${can('comparison')?nav('comparison','Quotation Comparison','ti-scale',active):''}${can('orders')?nav('orders','Purchase Orders','ti-shopping-cart',active):''}${can('receipts')?nav('receipts','Goods Receipts','ti-package',active):''}${can('invoices')?nav('invoices','Vendor Invoices','ti-receipt',active):''}${can('payments')?nav('payments','Payments','ti-credit-card',active):''}<div class="nav-title">MASTER DATA</div>${can('vendors')?nav('vendors','Vendors','ti-building-store',active):''}${can('products')?nav('products','Products','ti-box',active):''}${can('users')?nav('users','User & Role Management','ti-users',active):''}<div class="nav-title">REPORTS</div>${can('reports')?nav('reports','Reports','ti-chart-bar',active):''}${can('activities')?nav('activities','Activities','ti-activity',active):''}</div><div class="sidebar-bottom"><div class="sidebar-current-user"><b>${esc(currentUser()?.name||'User')}</b><span>${esc(currentUser()?.role||'')}</span></div><button onclick="logout()"><i class="ti ti-logout"></i> Sign out</button></div></aside><main class="main"><header class="top"><button class="mobile-menu" onclick="document.getElementById('side').classList.toggle('open')"><i class="ti ti-menu-2"></i></button><div><h1>${title}</h1><p>${sub}</p></div><div class="user"><span>${esc(currentUser()?.name||'Admin User')}</span><b>${esc((currentUser()?.name||'AU').split(' ').map(v=>v[0]).join('').slice(0,2).toUpperCase())}</b></div></header><section class="content">${body}</section></main></div><div id="toast"></div>`;}
function nav(id,label,icon,a){return `<a class="nav-item ${a===id?'active':''}" href="${id}.html"><i class="ti ${icon}"></i><span>${label}</span></a>`} function logout(){logActivity('Sign Out','Authentication','User signed out');sessionStorage.removeItem('purchase_user');location.href='index.html'} function need(){if(!sessionStorage.getItem('purchase_user'))location.href='index.html'} function money(n){return '₨ '+Number(n||0).toLocaleString('en-PK')} function stat(label,val,icon){return `<div class="stat-card"><div class="stat-icon"><i class="ti ${icon}"></i></div><div><div class="stat-label">${label}</div><div class="stat-value">${val}</div></div></div>`} function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty">No records found</td></tr>`}</tbody></table></div>`}
function status(s){return `<span class="badge ${s.toLowerCase().replaceAll(' ','-')}">${esc(s)}</span>`}function formModal(title,fields,submit){return `<div class="modal" id="modal"><div class="modal-box"><div class="modal-head"><h3>${title}</h3><button onclick="closeModal()">×</button></div><div class="modal-body">${fields}</div><div class="modal-foot"><button class="btn-secondary" onclick="closeModal()">Cancel</button><button class="btn-primary" onclick="${submit}">Save</button></div></div></div>`}function closeModal(){const m=document.getElementById('modal');if(m)m.remove();document.body.classList.remove('modal-open')}
function openModal(html){closeModal();document.body.insertAdjacentHTML('beforeend',html);const m=document.getElementById('modal');if(m){document.body.classList.add('modal-open');requestAnimationFrame(()=>m.classList.add('is-open'));}}
function bindModalEvents(){if(window.__modalEventsBound)return;window.__modalEventsBound=true;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('modal'))closeModal()});document.addEventListener('click',e=>{const m=document.getElementById('modal');if(m&&e.target===m)closeModal()});}
bindModalEvents()
function openVendor(){openModal(formModal('Add Vendor',`<div class="grid2"><label>Vendor Name<input id="vname"></label><label>Contact Person<input id="vcontact"></label><label>Phone<input id="vphone"></label><label>Email<input id="vemail"></label><label>Category<input id="vcat" placeholder="e.g. IT Equipment"></label></div>`,'saveVendor()'))}function saveVendor(){let x=db();x.vendors.push({id:Date.now(),name:vname.value,contact:vcontact.value,phone:vphone.value,email:vemail.value,category:vcat.value,status:'Active'});recordActivity(x,'Created','Vendors','Vendor added: '+vname.value,'Vendor');save(x);closeModal();renderVendors();toast('Vendor added')}
function requestItemRow(i=0,item={}){const x=db();return `<div class="request-item" data-item="${i}"><div class="item-grid"><label>Product / Service<select class="req-product" onchange="syncRequestRate(this)"><option value="">Select product</option>${x.products.map(p=>`<option value="${p.id}" data-rate="${p.rate}" ${String(item.productId)===String(p.id)?'selected':''}>${esc(p.name)} (${esc(p.sku)})</option>`).join('')}</select></label><label>Description<input class="req-desc" value="${esc(item.description||'')}" placeholder="Optional specification"></label><label>Quantity<input class="req-qty" type="number" min="0.01" step="0.01" value="${item.quantity||1}" oninput="recalcRequest()"></label><label>Estimated Rate<input class="req-rate" type="number" min="0" step="0.01" value="${item.rate||0}" oninput="recalcRequest()"></label><label>Unit<select class="req-unit"><option>Each</option><option>Box</option><option>Pack</option><option>Kg</option><option>Liter</option><option>Service</option></select></label><div class="item-total"><span>Total</span><b class="req-total">${money((item.quantity||1)*(item.rate||0))}</b></div></div><button type="button" class="remove-item" onclick="removeRequestItem(this)" title="Remove item"><i class="ti ti-trash"></i></button></div>`}
function openRequest(){const today=new Date().toISOString().slice(0,10);openModal(`<div class="modal" id="modal"><div class="modal-box request-modal"><div class="modal-head"><div><h3>New Purchase Request</h3><small>Create an internal request for goods or services</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="grid2"><label>Department<select id="rdept"><option>Administration</option><option>Finance</option><option>Human Resources</option><option>IT</option><option>Sales</option><option>Operations</option></select></label><label>Required Date<input id="rdate" type="date" value="${today}"></label></div><label>Justification<textarea id="rjust" rows="3" placeholder="Why is this purchase required?"></textarea></label><div class="items-head"><div><b>Request Items</b><small>Add the products/services and estimated cost</small></div><button type="button" class="btn-secondary" onclick="addRequestItem()"><i class="ti ti-plus"></i> Add Item</button></div><div id="request-items">${requestItemRow(0,{})}</div><div class="request-summary"><span>Estimated Total</span><strong id="request-total">₨ 0</strong></div><div><label>Attachment</label><input id="rfile" type="file" class="file-input" accept=".pdf,.doc,.docx,.jpg,.jpeg,.png,.xlsx,.xls"><small class="hint">Demo mode stores the file name only; no file is uploaded.</small></div></div><div class="modal-foot"><button class="btn-secondary" onclick="closeModal()">Cancel</button><button class="btn-primary" onclick="saveRequest()"><i class="ti ti-send"></i> Submit Request</button></div></div></div>`);recalcRequest()}
function addRequestItem(){const wrap=document.getElementById('request-items');wrap.insertAdjacentHTML('beforeend',requestItemRow(wrap.children.length,{}));}
function removeRequestItem(btn){const rows=document.querySelectorAll('#request-items .request-item');if(rows.length===1){toast('At least one item is required');return}btn.closest('.request-item').remove();recalcRequest()}
function syncRequestRate(sel){const opt=sel.selectedOptions[0];const row=sel.closest('.request-item');if(opt?.dataset.rate && Number(row.querySelector('.req-rate').value)===0)row.querySelector('.req-rate').value=opt.dataset.rate;recalcRequest()}
function recalcRequest(){let total=0;document.querySelectorAll('#request-items .request-item').forEach(row=>{const q=Number(row.querySelector('.req-qty').value||0),r=Number(row.querySelector('.req-rate').value||0),t=q*r;total+=t;row.querySelector('.req-total').textContent=money(t)});const out=document.getElementById('request-total');if(out)out.textContent=money(total)}
function saveRequest(){const x=db(),rows=[...document.querySelectorAll('#request-items .request-item')];const items=rows.map(row=>{const product=row.querySelector('.req-product'),opt=product.selectedOptions[0];return {productId:product.value||null,productName:opt?.textContent?.split(' (')[0]||'',description:row.querySelector('.req-desc').value.trim(),quantity:Number(row.querySelector('.req-qty').value||0),rate:Number(row.querySelector('.req-rate').value||0),unit:row.querySelector('.req-unit').value,total:Number(row.querySelector('.req-qty').value||0)*Number(row.querySelector('.req-rate').value||0)}});if(items.some(i=>!i.productId||i.quantity<=0)){toast('Please select a product and enter valid quantities');return}const total=items.reduce((a,i)=>a+i.total,0),next=(x.requests.length?Math.max(...x.requests.map(r=>Number(String(r.requestNo).split('-').pop())||0))+1:1);const id=Date.now();x.requests.unshift({id,requestNo:'PR-2026-'+String(next).padStart(3,'0'),requester:currentUser()?.name||'User',department:document.getElementById('rdept').value,date:document.getElementById('rdate').value,status:'Pending Approval',items:items.length,total,justification:document.getElementById('rjust').value.trim(),lineItems:items,attachment:document.getElementById('rfile')?.files[0]?.name||'',createdAt:new Date().toISOString()});recordActivity(x,'Created','Purchase Requests','Purchase request '+('PR-2026-'+String(next).padStart(3,'0'))+' submitted for approval','PR-2026-'+String(next).padStart(3,'0'));save(x);closeModal();renderRequests();toast('Purchase request submitted for approval')}
function requestActions(r){if(r.status==='Draft')return `<button class="btn-secondary" onclick="submitRequest(${r.id})">Submit</button>`;if(r.status==='Pending Approval')return `<button class="btn-secondary" onclick="approveRequest(${r.id})">Approve</button> <button class="btn-secondary" onclick="rejectRequest(${r.id})">Reject</button>`;if(r.status==='Approved')return `<button class="btn-secondary" onclick="downloadPurchaseRequestPdf(${r.id})"><i class="ti ti-file-type-pdf"></i> Vendor PDF</button> <button class="btn-secondary" onclick="openRFQ(${r.id})"><i class="ti ti-file-description"></i> Create RFQ</button>`;return '—'}
function downloadPDF(title, html){
  const w=window.open('', '_blank', 'width=900,height=1100');
  if(!w){toast('Please allow pop-ups to generate the PDF');return}
  const logo='data:image/png;base64,';
  const printScript='<scr'+'ipt>window.onload=function(){setTimeout(function(){window.print()},250)};window.onafterprint=function(){setTimeout(function(){window.close()},300)};</scr'+'ipt>';
  const page='<!doctype html><html><head><meta charset="utf-8"><title>'+esc(title)+'</title><style>'+
    '@page{size:A4;margin:14mm}*{box-sizing:border-box}body{font-family:Arial,Helvetica,sans-serif;color:#202735;font-size:12px;margin:0}'+
    '.topline{display:flex;justify-content:space-between;align-items:center;font-size:10px;color:#111;margin-bottom:22px}'+
    '.header{display:grid;grid-template-columns:42% 58%;align-items:center;padding-bottom:13px;border-bottom:4px solid #243575}'+
    '.brand-area{display:flex;align-items:center;gap:14px}.brand-logo{width:88px;height:auto;object-fit:contain}'+
    '.brand-name{font-size:30px;line-height:1.1;font-weight:800;color:#243575}.brand-sub{font-size:15px;color:#222;margin-top:7px}'+
    '.head-right{text-align:right}.doc-title{font-size:24px;line-height:1.15;font-weight:800;color:#243575;text-transform:uppercase}'+
    '.generated{font-size:11px;font-weight:800;margin-top:16px;color:#242424}'+
    '.intro{margin-top:30px;border-left:6px solid #243575;padding:18px 20px 18px 18px}'+
    '.intro h2{font-size:22px;color:#243575;margin:0 0 8px}.intro p{font-size:13px;margin:0;color:#30343b}'+
    '.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:0 42px;margin-top:26px;margin-bottom:20px}'+
    '.field{padding:10px 0;border-bottom:1px solid #d9dde5}.field span{display:block;color:#353942;font-size:11px;letter-spacing:.2px;margin-bottom:7px}.field b{font-size:13px;color:#202735}'+
    '.section{margin:25px 0}.section h3{font-size:14px;color:#243575;margin:0 0 9px;text-transform:uppercase}'+
    '.note{background:#f7f8fa;border:1px solid #d9dde5;padding:12px;margin-top:14px;white-space:pre-wrap}.total{margin-top:15px;text-align:right;font-size:17px;font-weight:800;color:#243575}'+
    '.footer{border-top:1px solid #d9dde5;margin-top:30px;padding-top:8px;color:#6b7280;font-size:9px;text-align:center}'+
    'table{width:100%;border-collapse:collapse;margin-top:8px}th,td{border:1px solid #cfd4dd;padding:8px;text-align:left;vertical-align:top}th{background:#f0f2f5;color:#202735;font-weight:800}'+
    '</style></head><body>'+
    '<div class="topline"><span>'+new Date().toLocaleDateString()+'</span><span>'+esc(title)+'</span></div>'+
    '<div class="header"><div class="brand-area"><img class="brand-logo" src="'+logo+'"><div><div class="brand-name">Dexterra</div><div class="brand-sub">Purchase &amp; Procurement Management</div></div></div>'+
    '<div class="head-right"><div class="doc-title">'+esc(title)+'</div><div class="generated">GENERATED '+new Date().toLocaleString()+'</div></div></div>'+
    html+
    '<div class="footer">Dexterra | Purchase &amp; Procurement Management | This document is issued for procurement purposes.</div>'+
    printScript+'</body></html>';
  w.document.open();w.document.write(page);w.document.close();
}
function pdfField(label,value){return `<div class="field"><span>${esc(label)}</span><b>${esc(value==null||value===''?'—':value)}</b></div>`}
function pdfTable(headers,rows){return `<table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
function requestDetails(id){const x=db(),r=x.requests.find(a=>a.id===id);if(!r)return;const items=r.lineItems||[];openModal(`<div class="modal" id="modal"><div class="modal-box request-modal"><div class="modal-head"><div><h3>${esc(r.requestNo)}</h3><small>Purchase request details</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="detail-grid"><div><span>Department</span><b>${esc(r.department)}</b></div><div><span>Requester</span><b>${esc(r.requester)}</b></div><div><span>Required Date</span><b>${esc(r.date)}</b></div><div><span>Status</span><b>${status(r.status)}</b></div></div><div class="detail-note"><b>Justification</b><p>${esc(r.justification||'No justification provided.')}</p></div>${table(['Product','Description','Qty','Rate','Total'],items.map(i=>`<tr><td><b>${esc(i.productName)}</b></td><td>${esc(i.description||'—')}</td><td>${i.quantity} ${esc(i.unit||'')}</td><td>${money(i.rate)}</td><td>${money(i.total)}</td></tr>`).join(''))}<div class="request-summary"><span>Estimated Total</span><strong>${money(r.total)}</strong></div>${r.attachment?`<div class="hint"><i class="ti ti-paperclip"></i> ${esc(r.attachment)}</div>`:''}</div><div class="modal-foot"><button class="btn-secondary" onclick="closeModal()">Close</button>${requestActions(r)}</div></div></div>`)}
function downloadPurchaseRequestPdf(id){
 const x=db(),r=(x.requests||[]).find(a=>a.id===id);
 if(!r)return;
 if(r.status!=='Approved'){toast('Purchase Request PDF is available only after approval');return}
 const items=r.lineItems||[];
 const rows=items.map((i,n)=>`<tr><td>${n+1}</td><td><b>${esc(i.productName||'')}</b></td><td>${esc(i.description||'—')}</td><td>${esc(i.quantity||0)}</td><td>${esc(i.unit||'—')}</td></tr>`).join('');
 const html=`
 <div class="vendor-doc-title">
   <h1>Request for Quotation</h1>
   <p>Purchase Request Reference: <b>${esc(r.requestNo)}</b> &nbsp;•&nbsp; Approved Procurement Requirement</p>
 </div>
 <div class="grid">
   <div class="field"><span>Purchase Request No.</span><b>${esc(r.requestNo||'—')}</b></div>
   <div class="field"><span>Request Date</span><b>${esc(r.date||'—')}</b></div>
   <div class="field"><span>Department</span><b>${esc(r.department||'—')}</b></div>
   <div class="field"><span>Required By</span><b>${esc(r.requiredDate||r.date||'—')}</b></div>
   <div class="field"><span>Request Status</span><b><span class="status-approved">Approved</span></b></div>
   <div class="field"><span>Requester</span><b>${esc(r.requester||'—')}</b></div>
 </div>
 <div class="section">
   <h3>Quotation Requirements</h3>
   <p class="intro">Dear Vendor, please review the following procurement requirements and submit your best quotation against the requested items. <b>No internal estimated pricing is disclosed in this document.</b></p>
   <table class="item-table"><thead><tr><th>#</th><th>Product / Service</th><th>Description / Specification</th><th>Quantity</th><th>Unit</th></tr></thead><tbody>${rows||`<tr><td colspan="5">No items specified.</td></tr>`}</tbody></table>
 </div>
 <div class="instruction">
   <strong>Vendor Submission Instructions</strong><br>
   Please provide your quotation separately, clearly mentioning your unit rates, applicable taxes, delivery lead time, quotation validity and payment terms. Kindly reference <b>${esc(r.requestNo)}</b> on your quotation.
 </div>
 <div class="section">
   <h3>Justification / Additional Requirements</h3>
   <p class="intro">${esc(r.justification||'No additional requirements provided.')}</p>
 </div>
 <div class="signature-row">
   <div class="signature">Authorized by Procurement / Management</div>
   <div class="signature">Vendor Representative / Acknowledgement</div>
 </div>`;
 downloadPDF(`Request for Quotation - ${r.requestNo}`,html);
}
function tablePdf(headers, rows){
 return `<table style="width:100%;border-collapse:collapse;margin-top:10px"><thead><tr>${headers.map(h=>`<th style="text-align:left;background:#f3f4f6;border:1px solid #d1d5db;padding:8px">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" style="border:1px solid #d1d5db;padding:8px">No items</td></tr>`}</tbody></table>`;
}
function submitRequest(id){let x=db(),r=x.requests.find(a=>a.id===id);if(r){r.status='Pending Approval';save(x);renderRequests();toast('Request submitted for approval')}}
function approveRequest(id){let x=db(),r=x.requests.find(a=>a.id===id);if(r){r.status='Approved';r.approvedAt=new Date().toISOString();recordActivity(x,'Approved','Purchase Requests',r.requestNo+' approved',r.requestNo);save(x);renderRequests();toast('Request approved')}}
function rejectRequest(id){const reason=prompt('Reason for rejection:');if(reason===null)return;let x=db(),r=x.requests.find(a=>a.id===id);if(r){r.status='Rejected';r.rejectionReason=reason;recordActivity(x,'Rejected','Purchase Requests',r.requestNo+' rejected: '+reason,r.requestNo);save(x);renderRequests();toast('Request rejected')}}
function renderDashboard(){need();const x=db();const pending=x.requests.filter(r=>r.status==='Pending Approval').length;const open=x.orders.filter(r=>!['Completed','Cancelled'].includes(r.status)).length;const unpaid=x.invoices.filter(r=>r.status!=='Paid').length;layout('dashboard','Purchase Dashboard','Overview of procurement activity',`<div class="stats">${stat('Purchase Requests',x.requests.length,'ti-file-invoice')}${stat('Pending Approvals',pending,'ti-clock')}${stat('Open Purchase Orders',open,'ti-shopping-cart')}${stat('Unpaid Invoices',unpaid,'ti-receipt')}</div><div class="section-card"><div class="section-head"><div><div class="section-title">Purchase Requests</div><div style="font-size:11px;color:#9CA3AF;margin-top:3px">Latest procurement requests</div></div><a class="btn-primary" href="requests.html">View Requests</a></div>${table(['Request No.','Department','Requester','Date','Status','Amount'],x.requests.slice(0,8).map(r=>`<tr><td><b>${r.requestNo}</b></td><td>${esc(r.department)}</td><td>${esc(r.requester)}</td><td>${r.date}</td><td>${status(r.status)}</td><td>${money(r.total)}</td></tr>`).join(''))}</div>`)}
function renderVendors(){need();const x=db();layout('vendors','Vendors','Manage your procurement vendors',`<div class="section-card"><div class="section-head"><div class="section-title">Vendor List</div><button class="btn-primary" onclick="openVendor()"><i class="ti ti-plus"></i> Add Vendor</button></div><div class="filters"><input placeholder="Search vendors" oninput="filterRows(this.value)"></div><div id="vendor-table">${vendorRows(x.vendors)}</div></div>`)}function vendorRows(v){return table(['Vendor','Contact','Phone','Email','Category','Status'],v.map(r=>`<tr><td><b>${esc(r.name)}</b></td><td>${esc(r.contact)}</td><td>${esc(r.phone)}</td><td>${esc(r.email)}</td><td>${esc(r.category)}</td><td>${status(r.status)}</td></tr>`).join(''))}function filterRows(q){const x=db();document.getElementById('vendor-table').innerHTML=vendorRows(x.vendors.filter(v=>(v.name+' '+v.contact+' '+v.category).toLowerCase().includes(q.toLowerCase())))}
function renderProducts(){need();const x=db();layout('products','Products & Services','Manage items available for purchasing',`<div class="section-card"><div class="section-head"><div class="section-title">Product Catalog</div><button class="btn-primary" onclick="openProduct()"><i class="ti ti-plus"></i> Add Product</button></div>${table(['Product','SKU','Category','Unit','Default Rate'],x.products.map(r=>`<tr><td><b>${esc(r.name)}</b></td><td>${r.sku}</td><td>${r.category}</td><td>${r.unit}</td><td>${money(r.rate)}</td></tr>`).join(''))}</div>`)}function openProduct(){openModal(formModal('Add Product',`<div class="grid2"><label>Product Name<input id="pname"></label><label>SKU<input id="psku"></label><label>Category<input id="pcat"></label><label>Unit<input id="punit" value="Each"></label><label>Default Rate<input id="prate" type="number"></label></div>`,'saveProduct()'))}function saveProduct(){let x=db();x.products.push({id:Date.now(),name:pname.value,sku:psku.value,category:pcat.value,unit:punit.value,rate:Number(prate.value||0)});recordActivity(x,'Created','Products','Product added: '+pname.value,'Product');save(x);closeModal();renderProducts();toast('Product added')}
function renderRequests(){need();const x=db();const pending=x.requests.filter(r=>r.status==='Pending Approval').length,approved=x.requests.filter(r=>r.status==='Approved').length,total=x.requests.reduce((a,r)=>a+Number(r.total||0),0);layout('requests','Purchase Requests','Create and track internal purchase requests',`<div class="stats">${stat('Total Requests',x.requests.length,'ti-file-invoice')}${stat('Pending Approval',pending,'ti-clock')}${stat('Approved',approved,'ti-circle-check')}${stat('Estimated Value',money(total),'ti-cash')}</div><div class="section-card"><div class="section-head"><div><div class="section-title">Purchase Requests</div><div style="font-size:11px;color:#9CA3AF;margin-top:3px">Create, review and approve internal procurement requests</div></div><button class="btn-primary" onclick="openRequest()"><i class="ti ti-plus"></i> New Request</button></div><div class="filters"><input id="request-search" placeholder="Search request no., department or requester" oninput="filterRequests()"><select id="request-status" onchange="filterRequests()"><option value="">All Statuses</option><option>Draft</option><option>Pending Approval</option><option>Approved</option><option>Rejected</option></select><input id="request-date" type="date" onchange="filterRequests()"></div><div id="request-table">${requestRows(x.requests)}</div></div>`)}
function requestRows(rows){return table(['Request No.','Department','Requester','Required Date','Items','Estimated Total','Status','Actions'],rows.map(r=>`<tr><td><button class="link-btn" onclick="requestDetails(${r.id})">${esc(r.requestNo)}</button></td><td>${esc(r.department)}</td><td>${esc(r.requester)}</td><td>${esc(r.date)}</td><td>${r.lineItems?.length||r.items||0}</td><td>${money(r.total)}</td><td>${status(r.status)}</td><td>${requestActions(r)}</td></tr>`).join(''))}
function filterRequests(){const x=db(),q=(document.getElementById('request-search')?.value||'').toLowerCase(),s=document.getElementById('request-status')?.value||'',d=document.getElementById('request-date')?.value||'';const rows=x.requests.filter(r=>(!q||(r.requestNo+' '+r.department+' '+r.requester).toLowerCase().includes(q))&&(!s||r.status===s)&&(!d||r.date===d));document.getElementById('request-table').innerHTML=requestRows(rows)}
function simpleList(active,title,sub,key,headers,empty,addText){need();const x=db();layout(active,title,sub,`<div class="section-card"><div class="section-head"><div class="section-title">${title}</div>${addText?`<button class="btn-primary" onclick="toast('Module form ready for next build step')"><i class="ti ti-plus"></i> ${addText}</button>`:''}</div>${table(headers,(x[key]||[]).map(r=>`<tr><td><b>${esc(r.requestNo||r.rfqNo||r.quotationNo||r.poNo||r.grnNo||r.invoiceNo||r.paymentNo||'—')}</b></td><td>${esc(r.vendor||r.supplier||r.department||'—')}</td><td>${esc(r.date||'—')}</td><td>${status(r.status||'Draft')}</td><td>${money(r.total||r.amount||0)}</td></tr>`).join(''))}</div>`)}

function receiptEligibleOrders(x){return (x.orders||[]).filter(o=>['Approved','Sent to Vendor','Partially Received'].includes(o.status));}
function orderReceivedQty(x,poId,itemIndex){return (x.receipts||[]).filter(r=>String(r.poId)===String(poId)).reduce((sum,r)=>sum+Number(r.items?.[itemIndex]?.acceptedQty||0),0)}
function receiptRemaining(x,o,i){return Math.max(0,Number(o.items?.[i]?.quantity||0)-orderReceivedQty(x,o.id,i));}
function renderReceipts(){
 need();const x=db(),receipts=x.receipts||[],received=receipts.filter(r=>r.status==='Received').length,partial=receipts.filter(r=>r.status==='Partially Received').length,pending=receiptEligibleOrders(x).length;
 layout('receipts','Goods Receipts (GRN)','Receive, inspect and record goods against approved purchase orders',`<div class="stats">${stat('Total GRNs',receipts.length,'ti-package')}${stat('Received',received,'ti-circle-check')}${stat('Partial Receipts',partial,'ti-truck-delivery')}${stat('POs Awaiting Receipt',pending,'ti-clock')}</div><div class="section-card"><div class="section-head"><div><div class="section-title">Goods Receipts</div><div style="font-size:11px;color:#9CA3AF;margin-top:3px">Record accepted and rejected quantities against Purchase Orders</div></div><button class="btn-primary" onclick="openGRN()"><i class="ti ti-plus"></i> Create GRN</button></div><div class="filters"><input id="grn-search" placeholder="Search GRN, PO or vendor" oninput="filterReceipts()"><select id="grn-status" onchange="filterReceipts()"><option value="">All Statuses</option><option>Received</option><option>Partially Received</option><option>Rejected</option></select></div><div id="grn-table">${receiptRows(receipts)}</div></div>`);
}
function receiptRows(rows){return table(['GRN No.','PO No.','Vendor','Received Date','Items','Accepted Qty','Rejected Qty','Status','Actions'],rows.map(r=>{const a=(r.items||[]).reduce((n,i)=>n+Number(i.acceptedQty||0),0),rej=(r.items||[]).reduce((n,i)=>n+Number(i.rejectedQty||0),0);return `<tr><td><button class="link-btn" onclick="receiptDetails(${r.id})">${esc(r.grnNo)}</button></td><td>${esc(r.poNo||'—')}</td><td>${esc(r.vendorName||'—')}</td><td>${esc(r.receivedDate||'—')}</td><td>${(r.items||[]).length}</td><td><b>${a}</b></td><td>${rej}</td><td>${status(r.status)}</td><td><button class="btn-sm" onclick="receiptDetails(${r.id})"><i class="ti ti-eye"></i> View</button> <button class="btn-sm" onclick="downloadGRNPdf(${r.id})"><i class="ti ti-file-type-pdf"></i> PDF</button></td></tr>`}).join(''))}
function filterReceipts(){const x=db(),q=(document.getElementById('grn-search')?.value||'').toLowerCase(),st=document.getElementById('grn-status')?.value||'';document.getElementById('grn-table').innerHTML=receiptRows((x.receipts||[]).filter(r=>(!q||(r.grnNo+' '+r.poNo+' '+r.vendorName).toLowerCase().includes(q))&&(!st||r.status===st)))}
function openGRN(){const x=db(),orders=receiptEligibleOrders(x);if(!orders.length){toast('No approved or sent purchase orders are awaiting receipt');return}openModal(`<div class="modal" id="modal"><div class="modal-box request-modal grn-modal"><div class="modal-head"><div><h3>Create Goods Receipt</h3><small>Record physical delivery against a Purchase Order</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="grid2"><label>Purchase Order<select id="grn-po" onchange="loadGRNPO()"><option value="">Select PO</option>${orders.map(o=>`<option value="${o.id}">${esc(o.poNo)} — ${esc(o.vendorName)} — ${money(o.total)}</option>`).join('')}</select></label><label>Receipt Date<input id="grn-date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Warehouse / Location<input id="grn-location" placeholder="e.g. Main Store"></label><label>Received By<input id="grn-receiver" value="Admin User"></label></div><div id="grn-preview"><div class="detail-note"><b>Select a Purchase Order</b><p>PO items and remaining quantities will appear here.</p></div></div><label>Inspection Notes<textarea id="grn-notes" rows="3" placeholder="Condition, inspection remarks, delivery note number, etc."></textarea></label></div><div class="modal-foot"><button class="btn-secondary" onclick="closeModal()">Cancel</button><button class="btn-primary" onclick="saveGRN()"><i class="ti ti-device-floppy"></i> Save GRN</button></div></div></div>`);loadGRNPO()}
function loadGRNPO(){const x=db(),o=x.orders.find(a=>String(a.id)===String(document.getElementById('grn-po')?.value)),box=document.getElementById('grn-preview');if(!o||!box){if(box)box.innerHTML='<div class="detail-note"><b>Select a Purchase Order</b><p>PO items and remaining quantities will appear here.</p></div>';return}box.innerHTML=`<div class="detail-grid"><div><span>Vendor</span><b>${esc(o.vendorName)}</b></div><div><span>PO</span><b>${esc(o.poNo)}</b></div><div><span>RFQ</span><b>${esc(o.rfqNo||'—')}</b></div><div><span>PO Total</span><b>${money(o.total)}</b></div></div><div class="grn-items">${(o.items||[]).map((i,idx)=>{const rem=receiptRemaining(x,o,idx);return `<div class="grn-item" data-index="${idx}"><div><b>${esc(i.productName)}</b><small>Ordered: ${i.quantity} ${esc(i.unit||'')} · Previously accepted: ${Number(i.quantity||0)-rem}</small></div><div><label>Received<input class="grn-received" type="number" min="0" max="${rem}" step="0.01" value="${rem}" oninput="syncGRNRow(this)"></label></div><div><label>Accepted<input class="grn-accepted" type="number" min="0" max="${rem}" step="0.01" value="${rem}"></label></div><div><label>Rejected<input class="grn-rejected" type="number" min="0" max="${rem}" step="0.01" value="0"></label></div><div><label>Inspection<select class="grn-inspection"><option>Passed</option><option>Passed with Remarks</option><option>Failed</option><option>Pending Inspection</option></select></label></div><div><label>Remark<input class="grn-remark" placeholder="Optional"></label></div></div>`}).join('')}</div><div class="grn-help"><i class="ti ti-info-circle"></i> Received = physical quantity delivered. Accepted + Rejected must equal Received.</div>`}
function syncGRNRow(input){const row=input.closest('.grn-item'),received=Number(input.value||0);row.querySelector('.grn-accepted').max=received;row.querySelector('.grn-rejected').max=received;const accepted=Number(row.querySelector('.grn-accepted').value||0);if(accepted>received)row.querySelector('.grn-accepted').value=received;const rej=Number(row.querySelector('.grn-rejected').value||0);if(rej>received)row.querySelector('.grn-rejected').value=Math.max(0,received-Number(row.querySelector('.grn-accepted').value||0))}
function saveGRN(){const x=db(),po=x.orders.find(a=>String(a.id)===String(document.getElementById('grn-po')?.value));if(!po){toast('Select a purchase order');return}const date=document.getElementById('grn-date').value;if(!date){toast('Enter receipt date');return}const items=[...document.querySelectorAll('.grn-item')].map(row=>{const idx=Number(row.dataset.index),src=po.items[idx],received=Number(row.querySelector('.grn-received').value||0),accepted=Number(row.querySelector('.grn-accepted').value||0),rejected=Number(row.querySelector('.grn-rejected').value||0);return{productId:src.productId,productName:src.productName,unit:src.unit,orderedQty:Number(src.quantity||0),remainingQty:receiptRemaining(x,po,idx),receivedQty:received,acceptedQty:accepted,rejectedQty:rejected,inspection:row.querySelector('.grn-inspection').value,remark:row.querySelector('.grn-remark').value.trim()}});if(items.every(i=>i.receivedQty===0)){toast('Enter at least one received quantity');return}if(items.some(i=>i.acceptedQty+i.rejectedQty!==i.receivedQty)){toast('Accepted + Rejected must equal Received for every item');return}if(items.some(i=>i.receivedQty>i.remainingQty)){toast('Received quantity cannot exceed remaining PO quantity');return}if(items.some(i=>i.acceptedQty>i.receivedQty||i.rejectedQty>i.receivedQty)){toast('Accepted or rejected quantity cannot exceed received quantity');return}const acceptedAny=items.some(i=>i.acceptedQty>0),rejectedAny=items.some(i=>i.rejectedQty>0),allComplete=(po.items||[]).every((_,idx)=>receiptRemaining(x,po,idx)-Number(items[idx]?.acceptedQty||0)<=0);const next=(x.receipts||[]).length?Math.max(...x.receipts.map(a=>Number(String(a.grnNo||'').split('-').pop())||0))+1:1;x.receipts=x.receipts||[];x.receipts.unshift({id:Date.now(),grnNo:'GRN-2026-'+String(next).padStart(3,'0'),poId:po.id,poNo:po.poNo,quotationId:po.quotationId,rfqNo:po.rfqNo,requestNo:po.requestNo,vendorId:po.vendorId,vendorName:po.vendorName,receivedDate:date,location:document.getElementById('grn-location').value.trim(),receivedBy:document.getElementById('grn-receiver').value.trim(),items,status:allComplete&&acceptedAny?'Received':acceptedAny?'Partially Received':'Rejected',notes:document.getElementById('grn-notes').value.trim(),createdAt:new Date().toISOString()});po.status=allComplete&&acceptedAny?'Completed':acceptedAny?'Partially Received':po.status;po.receivedAt=new Date().toISOString();recordActivity(x,'Created','Goods Receipts','Goods receipt created for '+po.poNo,'GRN');save(x);closeModal();renderReceipts();toast('Goods Receipt created successfully')}
function receiptDetails(id){const x=db(),r=(x.receipts||[]).find(a=>a.id===id);if(!r)return;openModal(`<div class="modal" id="modal"><div class="modal-box request-modal"><div class="modal-head"><div><h3>${esc(r.grnNo)}</h3><small>${esc(r.vendorName)} — ${esc(r.poNo)}</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="detail-grid"><div><span>PO</span><b>${esc(r.poNo)}</b></div><div><span>Vendor</span><b>${esc(r.vendorName)}</b></div><div><span>Receipt Date</span><b>${esc(r.receivedDate)}</b></div><div><span>Status</span><b>${status(r.status)}</b></div><div><span>Location</span><b>${esc(r.location||'—')}</b></div><div><span>Received By</span><b>${esc(r.receivedBy||'—')}</b></div></div>${table(['Item','Ordered','Received','Accepted','Rejected','Inspection','Remark'],(r.items||[]).map(i=>`<tr><td>${esc(i.productName)}</td><td>${i.orderedQty}</td><td>${i.receivedQty}</td><td><b>${i.acceptedQty}</b></td><td>${i.rejectedQty}</td><td>${esc(i.inspection)}</td><td>${esc(i.remark||'—')}</td></tr>`).join(''))}${r.notes?`<div class="detail-note"><b>Inspection Notes</b><p>${esc(r.notes)}</p></div>`:''}</div><div class="modal-foot"><button class="btn-secondary" onclick="downloadGRNPdf(${r.id})"><i class="ti ti-file-type-pdf"></i> PDF</button><button class="btn-secondary" onclick="closeModal()">Close</button>${r.status!=='Rejected'?`<button class="btn-primary" onclick="closeModal();location.href='invoices.html'"><i class="ti ti-receipt"></i> Vendor Invoice</button>`:''}</div></div></div>`)}

window.addEventListener('DOMContentLoaded',()=>{const p=location.pathname.split('/').pop();const pages={'dashboard.html':['dashboard',renderDashboard],'vendors.html':['vendors',renderVendors],'products.html':['products',renderProducts],'requests.html':['requests',renderRequests],'rfqs.html':['rfqs',()=>simpleList('rfqs','RFQs','Request quotations from vendors','rfqs',['RFQ No.','Vendor','Date','Status','Amount'],'No RFQs','Create RFQ')],'quotations.html':['quotations',renderQuotations],'comparison.html':['comparison',renderComparison],'orders.html':['orders',renderOrders],'receipts.html':['receipts',renderReceipts],'invoices.html':['invoices',renderInvoices],'payments.html':['payments',renderPayments],'reports.html':['reports',()=>simpleList('reports','Reports','Purchase analytics and reports','requests',['Request No.','Department','Date','Status','Amount'],'No report data','')],'users.html':['users',renderUsers]};const entry=pages[p];if(entry&&guard(entry[0]))entry[1]();});
function renderRFQs(){need();const x=db();const approved=x.requests.filter(r=>r.status==='Approved');const pending=x.rfqs.filter(r=>r.status==='Draft').length;layout('rfqs','Request for Quotations','Create and manage vendor quotation requests',`<div class="stats">${stat('Total RFQs',x.rfqs.length,'ti-file-description')}${stat('Draft',pending,'ti-pencil')}${stat('Sent',x.rfqs.filter(r=>r.status==='Sent').length,'ti-send')}${stat('Responses',x.rfqs.filter(r=>r.status==='Response Received').length,'ti-message-check')}</div><div class="section-card"><div class="section-head"><div><div class="section-title">RFQ List</div><div style="font-size:11px;color:#9CA3AF;margin-top:3px">Request quotations from approved purchase requests</div></div><button class="btn-primary" onclick="openRFQ()"><i class="ti ti-plus"></i> Create RFQ</button></div><div class="filters"><input id="rfq-search" placeholder="Search RFQ, vendor or request" oninput="filterRFQs()"><select id="rfq-status" onchange="filterRFQs()"><option value="">All Statuses</option><option>Draft</option><option>Sent</option><option>Response Received</option><option>Closed</option></select></div><div id="rfq-table">${rfqRows(x.rfqs)}</div></div>`)}
function rfqRows(rows){return table(['RFQ No.','Purchase Request','Vendors','Issue Date','Due Date','Status','Actions'],rows.map(r=>`<tr><td><button class="link-btn" onclick="rfqDetails(${r.id})">${esc(r.rfqNo)}</button></td><td>${esc(r.requestNo||'—')}</td><td>${esc((r.vendors||[]).map(v=>v.name).join(', '))}</td><td>${esc(r.issueDate||'—')}</td><td>${esc(r.dueDate||'—')}</td><td>${status(r.status)}</td><td>${r.status==='Draft'?`<button class="btn-sm" onclick="sendRFQ(${r.id})"><i class="ti ti-send"></i> Send</button>`:''}</td></tr>`).join(''))}
function filterRFQs(){const x=db(),q=(document.getElementById('rfq-search')?.value||'').toLowerCase(),s=document.getElementById('rfq-status')?.value||'';document.getElementById('rfq-table').innerHTML=rfqRows(x.rfqs.filter(r=>(!q||(r.rfqNo+' '+r.requestNo+' '+(r.vendors||[]).map(v=>v.name).join(' ')).toLowerCase().includes(q))&&(!s||r.status===s)))}
function openRFQ(requestId=null){const x=db(),approved=x.requests.filter(r=>r.status==='Approved');if(!approved.length){toast('Approve a Purchase Request before creating an RFQ');return}openModal(`<div class="modal" id="modal"><div class="modal-box request-modal"><div class="modal-head"><div><h3>Create RFQ</h3><small>Request quotations from selected vendors</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="grid2"><label>Purchase Request<select id="rfq-request" onchange="loadRFQRequest()"><option value="">Select approved request</option>${approved.map(r=>`<option value="${r.id}" ${String(requestId)===String(r.id)?'selected':''}>${esc(r.requestNo)} — ${esc(r.department)} — ${money(r.total)}</option>`).join('')}</select></label><label>Quotation Due Date<input id="rfq-due" type="date"></label></div><label>Vendors<select id="rfq-vendors" multiple size="4">${x.vendors.filter(v=>v.status==='Active').map(v=>`<option value="${v.id}">${esc(v.name)} — ${esc(v.category)}</option>`).join('')}</select><small class="hint">Hold Ctrl/Cmd to select multiple vendors.</small></label><label>Notes<textarea id="rfq-notes" rows="3" placeholder="Delivery, warranty, payment terms or other requirements"></textarea></label><div id="rfq-preview" class="detail-note"><b>Select an approved purchase request</b><p>The request items will be included automatically.</p></div></div><div class="modal-foot"><button class="btn-secondary" onclick="closeModal()">Cancel</button><button class="btn-primary" onclick="saveRFQ()"><i class="ti ti-device-floppy"></i> Create RFQ</button></div></div></div>`); if(requestId) loadRFQRequest() }
function loadRFQRequest(){const x=db(),r=x.requests.find(a=>a.id==document.getElementById('rfq-request')?.value),p=document.getElementById('rfq-preview');if(!r||!p){return}p.innerHTML=`<b>${esc(r.requestNo)} — ${esc(r.department)}</b>${table(['Product','Qty','Unit','Estimated Rate','Total'],(r.lineItems||[]).map(i=>`<tr><td>${esc(i.productName)}</td><td>${i.quantity}</td><td>${esc(i.unit||'')}</td><td>${money(i.rate)}</td><td>${money(i.total)}</td></tr>`).join(''))}<div class="request-summary"><span>Estimated Total</span><strong>${money(r.total)}</strong></div>`}
function saveRFQ(){const x=db(),rid=document.getElementById('rfq-request')?.value,r=x.requests.find(a=>a.id==rid),vids=[...document.getElementById('rfq-vendors').selectedOptions].map(o=>Number(o.value)),vendors=x.vendors.filter(v=>vids.includes(Number(v.id)));if(!r){toast('Select an approved purchase request');return}if(!vendors.length){toast('Select at least one vendor');return}const due=document.getElementById('rfq-due').value;if(!due){toast('Select quotation due date');return}const next=x.rfqs.length?Math.max(...x.rfqs.map(a=>Number(String(a.rfqNo).split('-').pop())||0))+1:1;x.rfqs.unshift({id:Date.now(),rfqNo:'RFQ-2026-'+String(next).padStart(3,'0'),requestId:r.id,requestNo:r.requestNo,department:r.department,issueDate:new Date().toISOString().slice(0,10),dueDate:due,vendors:vendors.map(v=>({id:v.id,name:v.name,email:v.email,contact:v.contact})),items:r.lineItems||[],estimatedTotal:r.total,notes:document.getElementById('rfq-notes').value.trim(),status:'Draft'});recordActivity(x,'Created','RFQs','RFQ created: RFQ-2026-'+String(next).padStart(3,'0'),'RFQ-2026-'+String(next).padStart(3,'0'));save(x);closeModal();renderRFQs();toast('RFQ created successfully')}
function sendRFQ(id){const x=db(),r=x.rfqs.find(a=>a.id===id);if(r){r.status='Sent';r.sentAt=new Date().toISOString();recordActivity(x,'Sent','RFQs','RFQ '+r.rfqNo+' sent to vendors',r.rfqNo);save(x);renderRFQs();toast('RFQ marked as sent to vendors')}}
function rfqDetails(id){const x=db(),r=x.rfqs.find(a=>a.id===id);if(!r)return;openModal(`<div class="modal" id="modal"><div class="modal-box request-modal"><div class="modal-head"><div><h3>${esc(r.rfqNo)}</h3><small>RFQ details</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="detail-grid"><div><span>Purchase Request</span><b>${esc(r.requestNo)}</b></div><div><span>Issue Date</span><b>${esc(r.issueDate)}</b></div><div><span>Due Date</span><b>${esc(r.dueDate)}</b></div><div><span>Status</span><b>${status(r.status)}</b></div></div><div class="detail-note"><b>Vendors</b><p>${esc((r.vendors||[]).map(v=>v.name).join(', '))}</p></div>${table(['Product','Description','Qty','Unit','Estimated Rate','Total'],(r.items||[]).map(i=>`<tr><td>${esc(i.productName)}</td><td>${esc(i.description||'—')}</td><td>${i.quantity}</td><td>${esc(i.unit||'')}</td><td>${money(i.rate)}</td><td>${money(i.total)}</td></tr>`).join(''))}<div class="request-summary"><span>Estimated Total</span><strong>${money(r.estimatedTotal)}</strong></div>${r.notes?`<div class="detail-note"><b>Notes</b><p>${esc(r.notes)}</p></div>`:''}</div><div class="modal-foot"><button class="btn-secondary" onclick="downloadRFQPDF(${r.id})"><i class="ti ti-file-type-pdf"></i> PDF</button><button class="btn-secondary" onclick="closeModal()">Close</button>${r.status==='Draft'?`<button class="btn-primary" onclick="closeModal();sendRFQ(${r.id})"><i class="ti ti-send"></i> Send RFQ</button>`:''}</div></div></div>`)}

function renderQuotations(){need();const x=db();const received=x.quotations.filter(q=>q.status==='Received').length;const draft=x.quotations.filter(q=>q.status==='Draft').length;const total=x.quotations.reduce((a,q)=>a+Number(q.total||0),0);layout('quotations','Vendor Quotations','Record and manage quotations received from vendors',`<div class="stats">${stat('Total Quotations',x.quotations.length,'ti-file-dollar')}${stat('Draft',draft,'ti-pencil')}${stat('Received',received,'ti-check')}${stat('Quoted Value',money(total),'ti-currency-rupee')}</div><div class="section-card"><div class="section-head"><div><div class="section-title">Vendor Quotations</div><div style="font-size:11px;color:#9CA3AF;margin-top:3px">Enter vendor offers against sent RFQs</div></div><button class="btn-primary" onclick="openQuotation()"><i class="ti ti-plus"></i> Add Quotation</button></div><div class="filters"><input id="quotation-search" placeholder="Search quotation, vendor or RFQ" oninput="filterQuotations()"><select id="quotation-status" onchange="filterQuotations()"><option value="">All Statuses</option><option>Draft</option><option>Received</option><option>Under Review</option><option>Selected</option><option>Rejected</option></select></div><div id="quotation-table">${quotationRows(x.quotations)}</div></div>`)}
function quotationPdfReady(x,q){const rfq=(x.rfqs||[]).find(r=>String(r.id)===String(q.rfqId));return !!(rfq&&['Sent','Response Received','Closed'].includes(rfq.status)&&q.status!=='Rejected')}
function quotationRows(rows){const x=db();return table(['Quotation No.','RFQ No.','Vendor','Quote Date','Valid Until','Total','Status','Actions'],rows.map(q=>`<tr><td><button class="link-btn" onclick="quotationDetails(${q.id})">${esc(q.quotationNo)}</button></td><td>${esc(q.rfqNo||'—')}</td><td>${esc(q.vendorName||'—')}</td><td>${esc(q.quoteDate||'—')}</td><td>${esc(q.validUntil||'—')}</td><td><b>${money(q.total)}</b></td><td>${status(q.status)}</td><td><button class="btn-sm" onclick="quotationDetails(${q.id})"><i class="ti ti-eye"></i> View</button>${quotationPdfReady(x,q)?` <button class="btn-sm" onclick="downloadQuotationPdf(${q.id})"><i class="ti ti-file-type-pdf"></i> PDF</button>`:''}</td></tr>`).join(''))}
function filterQuotations(){const x=db(),q=(document.getElementById('quotation-search')?.value||'').toLowerCase(),s=document.getElementById('quotation-status')?.value||'';document.getElementById('quotation-table').innerHTML=quotationRows(x.quotations.filter(r=>(!q||(r.quotationNo+' '+r.rfqNo+' '+r.vendorName).toLowerCase().includes(q))&&(!s||r.status===s)))}
function openQuotation(){const x=db(),rfqs=x.rfqs.filter(r=>r.status==='Sent'||r.status==='Response Received');if(!rfqs.length){toast('Send an RFQ before recording a vendor quotation');return}openModal(`<div class="modal" id="modal"><div class="modal-box request-modal"><div class="modal-head"><div><h3>Add Vendor Quotation</h3><small>Record a vendor's commercial offer against an RFQ</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="grid2"><label>RFQ<select id="q-rfq" onchange="loadQuotationRFQ()"><option value="">Select sent RFQ</option>${rfqs.map(r=>`<option value="${r.id}">${esc(r.rfqNo)} — ${esc(r.requestNo)} — ${esc((r.vendors||[]).map(v=>v.name).join(', '))}</option>`).join('')}</select></label><label>Vendor<select id="q-vendor" onchange="loadQuotationVendor()"><option value="">Select vendor</option></select></label><label>Quote Date<input id="q-date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Valid Until<input id="q-valid" type="date"></label></div><div id="q-items"><div class="detail-note"><b>Select an RFQ</b><p>The RFQ items will be loaded here.</p></div></div><div class="grid2"><label>Delivery Time<input id="q-delivery" placeholder="e.g. 7 days"></label><label>Payment Terms<input id="q-payment" placeholder="e.g. 30 days credit"></label></div><label>Notes<textarea id="q-notes" rows="3" placeholder="Warranty, delivery, exclusions, special terms..."></textarea></label><label>Quotation Attachment<input id="q-file" type="file" class="file-input" accept=".pdf,.doc,.docx,.jpg,.jpeg,.png,.xlsx,.xls"><small class="hint">Demo mode stores the file name only.</small></label></div><div class="modal-foot"><button class="btn-secondary" onclick="closeModal()">Cancel</button><button class="btn-primary" onclick="saveQuotation()"><i class="ti ti-device-floppy"></i> Save Quotation</button></div></div></div>`)}
function loadQuotationRFQ(){const x=db(),r=x.rfqs.find(a=>a.id==document.getElementById('q-rfq')?.value),v=document.getElementById('q-vendor'),box=document.getElementById('q-items');if(!r||!v)return;v.innerHTML='<option value="">Select vendor</option>'+(r.vendors||[]).map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('');box.innerHTML=`<div class="items-head"><div><b>Quoted Items</b><small>Enter vendor rates, tax and discount for each item</small></div></div><div id="quotation-items">${quotationItemRows(r.items||[])}</div><div class="request-summary"><span>Quoted Total</span><strong id="quotation-total">${money(0)}</strong></div>`;recalcQuotation()}
function quotationItemRows(items){return items.map((i,n)=>`<div class="request-item quotation-item" data-index="${n}"><div class="item-grid"><div><label>Product / Service</label><input class="q-product" value="${esc(i.productName||'')}" readonly></div><div><label>Qty</label><input class="q-qty" type="number" value="${i.quantity||0}" readonly></div><div><label>Unit</label><input class="q-unit" value="${esc(i.unit||'')}" readonly></div><div><label>Quoted Rate</label><input class="q-rate" type="number" min="0" step="0.01" value="0" oninput="recalcQuotation()"></div><div><label>Tax %</label><input class="q-tax" type="number" min="0" step="0.01" value="0" oninput="recalcQuotation()"></div><div><label>Discount %</label><input class="q-discount" type="number" min="0" max="100" step="0.01" value="0" oninput="recalcQuotation()"></div><div class="item-total"><span>Line Total</span><b class="q-line-total">${money(0)}</b></div></div></div>`).join('')}
function loadQuotationVendor(){const rfqId=document.getElementById('q-rfq')?.value,v=document.getElementById('q-vendor')?.value;if(!rfqId||!v)return;const x=db(),r=x.rfqs.find(a=>a.id==rfqId),vendor=(r?.vendors||[]).find(a=>a.id==v);if(vendor)document.getElementById('q-notes').placeholder=`Quotation from ${vendor.name}: warranty, delivery, exclusions...`}
function recalcQuotation(){let total=0;document.querySelectorAll('#quotation-items .quotation-item').forEach(row=>{const qty=Number(row.querySelector('.q-qty').value||0),rate=Number(row.querySelector('.q-rate').value||0),tax=Number(row.querySelector('.q-tax').value||0),discount=Number(row.querySelector('.q-discount').value||0);const subtotal=qty*rate;const line=subtotal+(subtotal*tax/100)-(subtotal*discount/100);total+=line;row.querySelector('.q-line-total').textContent=money(line)});const out=document.getElementById('quotation-total');if(out)out.textContent=money(total)}
function saveQuotation(){const x=db(),rfq=x.rfqs.find(a=>a.id==document.getElementById('q-rfq')?.value),vendor=(rfq?.vendors||[]).find(a=>a.id==document.getElementById('q-vendor')?.value);if(!rfq){toast('Select an RFQ');return}if(!vendor){toast('Select the vendor');return}const quoteDate=document.getElementById('q-date').value,validUntil=document.getElementById('q-valid').value;if(!quoteDate||!validUntil){toast('Enter quote date and validity date');return}const items=[...document.querySelectorAll('#quotation-items .quotation-item')].map((row,i)=>{const src=rfq.items[i],qty=Number(row.querySelector('.q-qty').value||0),rate=Number(row.querySelector('.q-rate').value||0),tax=Number(row.querySelector('.q-tax').value||0),discount=Number(row.querySelector('.q-discount').value||0),subtotal=qty*rate,line=subtotal+(subtotal*tax/100)-(subtotal*discount/100);return{productId:src.productId,productName:src.productName,description:src.description||'',quantity:qty,unit:src.unit,quotedRate:rate,taxPercent:tax,discountPercent:discount,subtotal,total:line}});if(items.some(i=>i.quotedRate<=0)){toast('Enter a quoted rate for every item');return}const total=items.reduce((a,i)=>a+i.total,0),next=x.quotations.length?Math.max(...x.quotations.map(a=>Number(String(a.quotationNo).split('-').pop())||0))+1:1;const file=document.getElementById('q-file')?.files?.[0];x.quotations.unshift({id:Date.now(),quotationNo:'VQ-2026-'+String(next).padStart(3,'0'),rfqId:rfq.id,rfqNo:rfq.rfqNo,requestNo:rfq.requestNo,vendorId:vendor.id,vendorName:vendor.name,vendorContact:vendor.contact,vendorEmail:vendor.email,quoteDate,validUntil,items,total,deliveryTime:document.getElementById('q-delivery').value.trim(),paymentTerms:document.getElementById('q-payment').value.trim(),notes:document.getElementById('q-notes').value.trim(),attachment:file?file.name:'',status:'Received'});rfq.status='Response Received';recordActivity(x,'Received','Vendor Quotations','Vendor quotation '+x.quotations[0].quotationNo+' recorded for '+rfq.rfqNo,x.quotations[0].quotationNo);save(x);closeModal();renderQuotations();toast('Vendor quotation recorded successfully')}
function quotationDetails(id){const x=db(),q=x.quotations.find(a=>a.id===id);if(!q)return;const pdfReady=quotationPdfReady(x,q);openModal(`<div class="modal" id="modal"><div class="modal-box request-modal"><div class="modal-head"><div><h3>${esc(q.quotationNo)}</h3><small>${esc(q.vendorName)} — ${esc(q.rfqNo)}</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="detail-grid"><div><span>Vendor</span><b>${esc(q.vendorName)}</b></div><div><span>RFQ</span><b>${esc(q.rfqNo)}</b></div><div><span>Quote Date</span><b>${esc(q.quoteDate)}</b></div><div><span>Valid Until</span><b>${esc(q.validUntil)}</b></div><div><span>Status</span><b>${status(q.status)}</b></div><div><span>Total</span><b>${money(q.total)}</b></div></div>${table(['Product','Qty','Rate','Tax','Discount','Total'],(q.items||[]).map(i=>`<tr><td>${esc(i.productName)}</td><td>${i.quantity}</td><td>${money(i.quotedRate)}</td><td>${i.taxPercent}%</td><td>${i.discountPercent}%</td><td><b>${money(i.total)}</b></td></tr>`).join(''))}<div class="detail-grid"><div><span>Delivery</span><b>${esc(q.deliveryTime||'—')}</b></div><div><span>Payment Terms</span><b>${esc(q.paymentTerms||'—')}</b></div></div>${q.notes?`<div class="detail-note"><b>Notes</b><p>${esc(q.notes)}</p></div>`:''}${q.attachment?`<div class="detail-note"><b>Attachment</b><p>${esc(q.attachment)}</p></div>`:''}${pdfReady?`<div class="detail-note"><b>Quotation PDF Available</b><p>This quotation is linked to a sent RFQ and can be downloaded and shared with the vendor before quotation comparison.</p></div>`:''}</div><div class="modal-foot">${pdfReady?`<button class="btn-secondary" onclick="downloadQuotationPdf(${q.id})"><i class="ti ti-file-type-pdf"></i> Quotation PDF</button>`:''}<button class="btn-secondary" onclick="closeModal()">Close</button>${q.status==='Received'?`<button class="btn-primary" onclick="closeModal();location.href='comparison.html'"><i class="ti ti-scale"></i> Compare RFQ</button>`:''}</div></div></div>`) }
function invoiceEligiblePOs(x){return (x.orders||[]).filter(o=>['Sent to Vendor','Partially Received','Completed'].includes(o.status));}
function acceptedQtyForInvoice(x,poId,itemIndex){return (x.receipts||[]).filter(r=>String(r.poId)===String(poId)).reduce((sum,r)=>sum+Number(r.items?.[itemIndex]?.acceptedQty||0),0)}
function receivedValue(x,o){return (o.items||[]).reduce((sum,item,i)=>{const qty=acceptedQtyForInvoice(x,o.id,i);const base=qty*Number(item.rate||item.quotedRate||0);return sum+base+(base*Number(item.taxPercent||0)/100)-(base*Number(item.discountPercent||0)/100)},0)}
function invoiceMatch(x,inv){const po=(x.orders||[]).find(o=>String(o.id)===String(inv.poId));if(!po)return {status:'Exception',reason:'Purchase Order not found',po:null,received:0};const received=receivedValue(x,po),amount=Number(inv.amount||0),poTotal=Number(po.total||0),tol=0.01;let status='Matched',reason='PO and accepted GRN value match the invoice';if(received<=tol){status='Exception';reason='No accepted goods are available for this PO';}else if(Math.abs(amount-received)>tol){status='Exception';reason=`Invoice ${money(amount)} differs from accepted GRN value ${money(received)}`;}else if(Math.abs(amount-poTotal)>tol){status='Exception';reason=`Invoice ${money(amount)} differs from PO total ${money(poTotal)}`;}return {status,reason,po,received};}
function renderInvoices(){need();const x=db(),invs=x.invoices||[],unpaid=invs.filter(i=>i.status!=='Paid').length,matched=invs.filter(i=>i.matchStatus==='Matched').length,exceptions=invs.filter(i=>i.matchStatus==='Exception').length,total=invs.reduce((a,i)=>a+Number(i.amount||0),0);layout('invoices','Vendor Invoices','Record vendor invoices and validate them against Purchase Orders and Goods Receipts',`<div class="stats">${stat('Total Invoices',invs.length,'ti-receipt')}${stat('Unpaid',unpaid,'ti-clock')}${stat('3-Way Matched',matched,'ti-circle-check')}${stat('Exceptions',exceptions,'ti-alert-triangle')}</div><div class="section-card"><div class="section-head"><div><div class="section-title">Vendor Invoices</div><div style="font-size:11px;color:#9CA3AF;margin-top:3px">3-way match: Purchase Order vs accepted Goods Receipt vs Vendor Invoice</div></div><button class="btn-primary" onclick="openInvoice()"><i class="ti ti-plus"></i> Add Vendor Invoice</button></div><div class="filters"><input id="invoice-search" placeholder="Search invoice, PO or vendor" oninput="filterInvoices()"><select id="invoice-status" onchange="filterInvoices()"><option value="">All Statuses</option><option>Draft</option><option>Matched</option><option>Exception</option><option>Approved</option><option>Paid</option></select></div><div id="invoice-table">${invoiceRows(invs)}</div></div>`)}
function invoiceRows(rows){return table(['Invoice No.','PO No.','Vendor','Invoice Date','Due Date','Amount','3-Way Match','Status','Actions'],rows.map(i=>`<tr><td><button class="link-btn" onclick="invoiceDetails(${i.id})">${esc(i.invoiceNo)}</button></td><td>${esc(i.poNo||'—')}</td><td>${esc(i.vendorName||'—')}</td><td>${esc(i.invoiceDate||'—')}</td><td>${esc(i.dueDate||'—')}</td><td><b>${money(i.amount)}</b></td><td>${status(i.matchStatus||'Pending')}</td><td>${status(i.status||'Draft')}</td><td><button class="btn-sm" onclick="invoiceDetails(${i.id})"><i class="ti ti-eye"></i> View</button> <button class="btn-sm" onclick="downloadInvoicePdf(${i.id})"><i class="ti ti-file-type-pdf"></i> PDF</button></td></tr>`).join(''))}
function filterInvoices(){const x=db(),q=(document.getElementById('invoice-search')?.value||'').toLowerCase(),st=document.getElementById('invoice-status')?.value||'';document.getElementById('invoice-table').innerHTML=invoiceRows((x.invoices||[]).filter(i=>(!q||(i.invoiceNo+' '+i.poNo+' '+i.vendorName).toLowerCase().includes(q))&&(!st||i.status===st)))}
function openInvoice(){const x=db(),pos=invoiceEligiblePOs(x);if(!pos.length){toast('No purchase orders are available for invoicing');return}openModal(`<div class="modal" id="modal"><div class="modal-box request-modal"><div class="modal-head"><div><h3>Add Vendor Invoice</h3><small>Enter the supplier invoice and validate it against PO and accepted GRN quantities</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="grid2"><label>Purchase Order<select id="inv-po" onchange="loadInvoicePO()"><option value="">Select PO</option>${pos.map(o=>`<option value="${o.id}">${esc(o.poNo)} — ${esc(o.vendorName)} — ${money(o.total)}</option>`).join('')}</select></label><label>Invoice Number<input id="inv-no" placeholder="Vendor invoice number"></label><label>Invoice Date<input id="inv-date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Due Date<input id="inv-due" type="date"></label><label>Invoice Amount<input id="inv-amount" type="number" min="0" step="0.01" oninput="previewInvoiceMatch()"></label><label>Vendor Reference<input id="inv-ref" placeholder="Supplier reference / bill reference"></label></div><div id="invoice-preview"><div class="detail-note"><b>Select a Purchase Order</b><p>The PO, accepted GRN value and 3-way match result will appear here.</p></div></div><label>Notes<textarea id="inv-notes" rows="3" placeholder="Invoice notes or exception reason..."></textarea></label></div><div class="modal-foot"><button class="btn-secondary" onclick="closeModal()">Cancel</button><button class="btn-primary" onclick="saveInvoice()"><i class="ti ti-device-floppy"></i> Save Invoice</button></div></div></div>`);loadInvoicePO()}
function loadInvoicePO(){const x=db(),o=x.orders.find(a=>String(a.id)===String(document.getElementById('inv-po')?.value)),box=document.getElementById('invoice-preview');if(!box)return;if(!o){box.innerHTML='<div class="detail-note"><b>Select a Purchase Order</b><p>The PO, accepted GRN value and 3-way match result will appear here.</p></div>';return}const received=receivedValue(x,o),acceptedItems=(o.items||[]).map((item,i)=>({item,qty:acceptedQtyForInvoice(x,o.id,i)})).filter(a=>a.qty>0);box.innerHTML=`<div class="detail-grid"><div><span>Vendor</span><b>${esc(o.vendorName)}</b></div><div><span>PO</span><b>${esc(o.poNo)}</b></div><div><span>PO Total</span><b>${money(o.total)}</b></div><div><span>Accepted GRN Value</span><b>${money(received)}</b></div></div>${table(['Item','Accepted Qty','Rate','Line Value'],acceptedItems.length?acceptedItems.map(a=>`<tr><td>${esc(a.item.productName)}</td><td>${a.qty} ${esc(a.item.unit||'')}</td><td>${money(a.item.rate||a.item.quotedRate)}</td><td><b>${money(a.qty*Number(a.item.rate||a.item.quotedRate||0))}</b></td></tr>`).join(''):'<tr><td colspan="4">No accepted quantities found.</td></tr>')}<div id="invoice-match-preview" class="request-summary"><span>3-Way Match</span><strong>Enter invoice amount</strong></div>`;previewInvoiceMatch()}
function previewInvoiceMatch(){const x=db(),po=x.orders.find(a=>String(a.id)===String(document.getElementById('inv-po')?.value)),out=document.getElementById('invoice-match-preview');if(!po||!out)return;const amount=Number(document.getElementById('inv-amount')?.value||0),received=receivedValue(x,po);let ok=amount>0&&Math.abs(amount-received)<=0.01&&Math.abs(amount-Number(po.total||0))<=0.01;out.innerHTML=`<span>3-Way Match</span><strong class="${ok?'text-success':'text-danger'}">${ok?'Matched':'Exception'} · PO ${money(po.total)} · GRN ${money(received)} · Invoice ${money(amount)}</strong>`}
function saveInvoice(){const x=db(),po=x.orders.find(a=>String(a.id)===String(document.getElementById('inv-po')?.value));if(!po){toast('Select a purchase order');return}const invoiceNo=document.getElementById('inv-no').value.trim(),invoiceDate=document.getElementById('inv-date').value,dueDate=document.getElementById('inv-due').value,amount=Number(document.getElementById('inv-amount').value||0);if(!invoiceNo||!invoiceDate||!dueDate||amount<=0){toast('Enter invoice number, dates and a valid amount');return}if((x.invoices||[]).some(i=>String(i.invoiceNo).toLowerCase()===invoiceNo.toLowerCase())){toast('An invoice with this number already exists');return}const nextMatch=invoiceMatch(x,{poId:po.id,amount}),next=(x.invoices||[]).length?Math.max(...x.invoices.map(a=>Number(String(a.id).replace(/\D/g,''))||0))+1:Date.now();x.invoices=x.invoices||[];x.invoices.unshift({id:next,invoiceNo,poId:po.id,poNo:po.poNo,quotationId:po.quotationId,rfqNo:po.rfqNo,requestNo:po.requestNo,vendorId:po.vendorId,vendorName:po.vendorName,vendorEmail:po.vendorEmail,invoiceDate,dueDate,amount,referenceNo:document.getElementById('inv-ref').value.trim(),notes:document.getElementById('inv-notes').value.trim(),matchStatus:nextMatch.status,matchReason:nextMatch.reason,status:nextMatch.status==='Matched'?'Matched':'Exception',createdAt:new Date().toISOString()});recordActivity(x,'Created','Vendor Invoices','Vendor invoice '+invoiceNo+' recorded','Invoice');save(x);closeModal();renderInvoices();toast(nextMatch.status==='Matched'?'Invoice saved and 3-way matched':'Invoice saved with a 3-way match exception')}
function invoiceDetails(id){const x=db(),i=(x.invoices||[]).find(a=>a.id===id);if(!i)return;const m=invoiceMatch(x,i);openModal(`<div class="modal" id="modal"><div class="modal-box request-modal"><div class="modal-head"><div><h3>${esc(i.invoiceNo)}</h3><small>${esc(i.vendorName)} — ${esc(i.poNo)}</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="detail-grid"><div><span>Invoice No.</span><b>${esc(i.invoiceNo)}</b></div><div><span>Vendor</span><b>${esc(i.vendorName)}</b></div><div><span>Invoice Date</span><b>${esc(i.invoiceDate)}</b></div><div><span>Due Date</span><b>${esc(i.dueDate)}</b></div><div><span>PO Total</span><b>${money(m.po?.total||0)}</b></div><div><span>Accepted GRN Value</span><b>${money(m.received)}</b></div><div><span>Invoice Amount</span><b>${money(i.amount)}</b></div><div><span>3-Way Match</span><b>${status(i.matchStatus||m.status)}</b></div><div><span>Status</span><b>${status(i.status)}</b></div><div><span>Reference</span><b>${esc(i.referenceNo||'—')}</b></div></div><div class="detail-note ${i.matchStatus==='Matched'?'':'comparison-warning'}"><b>${i.matchStatus==='Matched'?'3-Way Match Passed':'3-Way Match Exception'}</b><p>${esc(i.matchReason||m.reason)}</p></div>${i.notes?`<div class="detail-note"><b>Notes</b><p>${esc(i.notes)}</p></div>`:''}</div><div class="modal-foot"><button class="btn-secondary" onclick="downloadInvoicePdf(${i.id})"><i class="ti ti-file-type-pdf"></i> PDF</button><button class="btn-secondary" onclick="closeModal()">Close</button>${i.status==='Matched'?`<button class="btn-primary" onclick="approveInvoice(${i.id})"><i class="ti ti-check"></i> Approve Invoice</button>`:''}</div></div></div>`)}
function approveInvoice(id){const x=db(),i=(x.invoices||[]).find(a=>a.id===id);if(!i)return;if(i.matchStatus!=='Matched'){toast('Only 3-way matched invoices can be approved');return}i.status='Approved';i.approvedAt=new Date().toISOString();recordActivity(x,'Approved','Vendor Invoices',i.invoiceNo+' approved',i.invoiceNo);save(x);closeModal();renderInvoices();toast('Vendor invoice approved')}

function setQuotationStatus(id,newStatus){const x=db(),q=x.quotations.find(a=>a.id===id);if(!q)return;q.status=newStatus;recordActivity(x,'Updated','Vendor Quotations',q.quotationNo+' marked as '+newStatus,q.quotationNo);save(x);closeModal();renderQuotations();toast('Quotation marked as '+newStatus)}

function activityRows(rows){return table(['Date & Time','User','Role','Module','Action','Details'],rows.map(a=>`<tr><td>${esc(new Date(a.createdAt).toLocaleString())}</td><td><b>${esc(a.userName||'Unknown')}</b><br><small>${esc(a.userEmail||'')}</small></td><td>${esc(a.role||'')}</td><td>${esc(a.module||'')}</td><td><span class="badge">${esc(a.action||'')}</span></td><td>${esc(a.details||'')}</td></tr>`).join(''))}
function renderActivities(){need();if(!guard('activities'))return;const x=db(),u=currentUser(),rows=(x.activities||[]).filter(a=>u?.role==='Admin'||String(a.userId)===String(u?.id)||(!a.userId&&a.userEmail===u?.email));layout('activities','Activity Log','Track all recorded activity across the purchase management system',`<div class="stats">${stat('Activities',rows.length,'ti-activity')}${stat('Today',rows.filter(a=>new Date(a.createdAt).toDateString()===new Date().toDateString()).length,'ti-calendar-event')}${stat('User',u?.role==='Admin'?'All Users':u?.name,'ti-user')}${stat('Access',u?.role==='Admin'?'All Activities':'My Activities','ti-shield-check')}</div><div class="section-card"><div class="section-head"><div><div class="section-title">${u?.role==='Admin'?'All User Activities':'My Activities'}</div><div style="font-size:11px;color:#9CA3AF;margin-top:3px">${u?.role==='Admin'?'You can review activity performed by every user.':'You can only view activity performed by your own account.'}</div></div></div><div class="filters"><input id="activity-search" placeholder="Search user, module, action or details" oninput="filterActivities()"><select id="activity-module" onchange="filterActivities()"><option value="">All Modules</option>${[...new Set(rows.map(a=>a.module).filter(Boolean))].sort().map(m=>`<option>${esc(m)}</option>`).join('')}</select><select id="activity-action" onchange="filterActivities()"><option value="">All Actions</option>${[...new Set(rows.map(a=>a.action).filter(Boolean))].sort().map(a=>`<option>${esc(a)}</option>`).join('')}</select></div><div id="activity-table">${activityRows(rows)}</div></div>`)}
function filterActivities(){const x=db(),u=currentUser(),q=(document.getElementById('activity-search')?.value||'').toLowerCase(),m=document.getElementById('activity-module')?.value||'',act=document.getElementById('activity-action')?.value||'';let rows=(x.activities||[]).filter(a=>u?.role==='Admin'||String(a.userId)===String(u?.id)||(!a.userId&&a.userEmail===u?.email));rows=rows.filter(a=>(!q||(a.userName+' '+a.userEmail+' '+a.module+' '+a.action+' '+a.details).toLowerCase().includes(q))&&(!m||a.module===m)&&(!act||a.action===act));document.getElementById('activity-table').innerHTML=activityRows(rows)}

document.addEventListener('DOMContentLoaded',()=>{const page=location.pathname.split('/').pop();if(page==='rfqs.html')renderRFQs();else if(page==='users.html')renderUsers();else if(page==='activities.html')renderActivities();});


function renderOrders(){
 need();const x=db(),orders=x.orders||[];const draft=orders.filter(o=>o.status==='Draft').length,approved=orders.filter(o=>o.status==='Approved').length,open=orders.filter(o=>!['Completed','Cancelled'].includes(o.status)).length,total=orders.reduce((a,o)=>a+Number(o.total||0),0);
 layout('orders','Purchase Orders','Create and manage purchase orders from selected quotations',`<div class="stats">${stat('Total POs',orders.length,'ti-shopping-cart')}${stat('Draft',draft,'ti-pencil')}${stat('Approved',approved,'ti-circle-check')}${stat('Open POs',open,'ti-truck-delivery')}</div><div class="section-card"><div class="section-head"><div><div class="section-title">Purchase Orders</div><div style="font-size:11px;color:#9CA3AF;margin-top:3px">Purchase orders are created from quotations selected in Quotation Comparison</div></div><button class="btn-primary" onclick="openPO()"><i class="ti ti-plus"></i> Create PO</button></div><div class="filters"><input id="po-search" placeholder="Search PO, vendor, RFQ or request" oninput="filterOrders()"><select id="po-status" onchange="filterOrders()"><option value="">All Statuses</option><option>Draft</option><option>Approved</option><option>Sent to Vendor</option><option>Partially Received</option><option>Completed</option><option>Cancelled</option></select></div><div id="po-table">${orderRows(orders)}</div></div>`);
}
function orderRows(rows){return table(['PO No.','RFQ / Request','Vendor','PO Date','Delivery','Total','Status','Actions'],rows.map(o=>`<tr><td><button class="link-btn" onclick="orderDetails(${o.id})">${esc(o.poNo)}</button></td><td>${esc(o.rfqNo||'—')}<br><small style="color:#9CA3AF">${esc(o.requestNo||'')}</small></td><td>${esc(o.vendorName||'—')}</td><td>${esc(o.poDate||'—')}</td><td>${esc(o.deliveryDate||o.deliveryTime||'—')}</td><td><b>${money(o.total)}</b></td><td>${status(o.status)}</td><td><button class="btn-sm" onclick="orderDetails(${o.id})"><i class="ti ti-eye"></i> View</button> <button class="btn-sm" onclick="downloadPOPdf(${o.id})"><i class="ti ti-file-type-pdf"></i> PDF</button></td></tr>`).join(''))}
function filterOrders(){const x=db(),q=(document.getElementById('po-search')?.value||'').toLowerCase(),st=document.getElementById('po-status')?.value||'';document.getElementById('po-table').innerHTML=orderRows((x.orders||[]).filter(o=>(!q||(o.poNo+' '+o.vendorName+' '+o.rfqNo+' '+o.requestNo).toLowerCase().includes(q))&&(!st||o.status===st)))}
function openPO(){const x=db(),selected=(x.quotations||[]).filter(q=>q.status==='Selected').filter(q=>!(x.orders||[]).some(o=>String(o.quotationId)===String(q.id)));if(!selected.length){toast('Select a quotation in Quotation Comparison before creating a PO');return}openModal(`<div class="modal" id="modal"><div class="modal-box request-modal"><div class="modal-head"><div><h3>Create Purchase Order</h3><small>Create a PO from a selected vendor quotation</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="grid2"><label>Selected Quotation<select id="po-quotation" onchange="loadPODetails()"><option value="">Select quotation</option>${selected.map(q=>`<option value="${q.id}">${esc(q.quotationNo)} — ${esc(q.vendorName)} — ${money(q.total)}</option>`).join('')}</select></label><label>PO Date<input id="po-date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Expected Delivery Date<input id="po-delivery-date" type="date"></label><label>Delivery Location<input id="po-location" placeholder="e.g. Main Store / Head Office"></label></div><div id="po-preview"><div class="detail-note"><b>Select a quotation</b><p>Vendor and quoted items will be loaded here.</p></div></div><div class="grid2"><label>Shipping / Other Charges<input id="po-shipping" type="number" min="0" step="0.01" value="0" oninput="recalcPO()"></label><label>Additional Discount<input id="po-extra-discount" type="number" min="0" step="0.01" value="0" oninput="recalcPO()"></label></div><label>Terms & Conditions<textarea id="po-terms" rows="3" placeholder="Delivery, warranty, inspection, payment and other PO terms..."></textarea></label></div><div class="modal-foot"><button class="btn-secondary" onclick="closeModal()">Cancel</button><button class="btn-primary" onclick="savePO()"><i class="ti ti-device-floppy"></i> Create Purchase Order</button></div></div></div>`);loadPODetails()}
function loadPODetails(){const x=db(),q=x.quotations.find(a=>String(a.id)===String(document.getElementById('po-quotation')?.value)),box=document.getElementById('po-preview');if(!q||!box){if(box)box.innerHTML='<div class="detail-note"><b>Select a quotation</b><p>Vendor and quoted items will be loaded here.</p></div>';return}box.innerHTML=`<div class="detail-grid"><div><span>Vendor</span><b>${esc(q.vendorName)}</b></div><div><span>RFQ</span><b>${esc(q.rfqNo)}</b></div><div><span>Quotation</span><b>${esc(q.quotationNo)}</b></div><div><span>Payment Terms</span><b>${esc(q.paymentTerms||'—')}</b></div></div><div style="margin-top:15px">${table(['Item','Qty','Unit','Rate','Tax','Discount','Line Total'],(q.items||[]).map(i=>`<tr><td>${esc(i.productName)}</td><td>${i.quantity}</td><td>${esc(i.unit||'')}</td><td>${money(i.quotedRate)}</td><td>${Number(i.taxPercent||0)}%</td><td>${Number(i.discountPercent||0)}%</td><td><b>${money(i.total)}</b></td></tr>`).join(''))}</div><div class="request-summary"><span>Quoted Total</span><strong id="po-quoted-total">${money(q.total)}</strong></div><div class="detail-note"><b>Vendor Terms</b><p>${esc(q.deliveryTime||'Delivery not specified')} · ${esc(q.paymentTerms||'Payment terms not specified')}${q.notes?' · '+esc(q.notes):''}</p></div>`;recalcPO()}
function recalcPO(){const x=db(),q=x.quotations.find(a=>String(a.id)===String(document.getElementById('po-quotation')?.value));if(!q)return;const shipping=Number(document.getElementById('po-shipping')?.value||0),discount=Number(document.getElementById('po-extra-discount')?.value||0),total=Math.max(0,Number(q.total||0)+shipping-discount),out=document.getElementById('po-quoted-total');if(out)out.textContent=money(total)}
function savePO(){const x=db(),qid=document.getElementById('po-quotation')?.value,q=x.quotations.find(a=>String(a.id)===String(qid));if(!q){toast('Select a selected quotation');return}if(q.status!=='Selected'){toast('Only selected quotations can become purchase orders');return}if((x.orders||[]).some(o=>String(o.quotationId)===String(q.id))){toast('A purchase order already exists for this quotation');return}const poDate=document.getElementById('po-date').value,deliveryDate=document.getElementById('po-delivery-date').value;if(!poDate||!deliveryDate){toast('Enter PO date and expected delivery date');return}const shipping=Number(document.getElementById('po-shipping').value||0),extraDiscount=Number(document.getElementById('po-extra-discount').value||0),subtotal=Number(q.total||0),total=Math.max(0,subtotal+shipping-extraDiscount),next=(x.orders||[]).length?Math.max(...x.orders.map(a=>Number(String(a.poNo||'').split('-').pop())||0))+1:1;const rfq=x.rfqs.find(r=>String(r.id)===String(q.rfqId));x.orders=x.orders||[];x.orders.unshift({id:Date.now(),poNo:'PO-2026-'+String(next).padStart(3,'0'),quotationId:q.id,quotationNo:q.quotationNo,rfqId:q.rfqId,rfqNo:q.rfqNo,requestNo:q.requestNo,vendorId:q.vendorId,vendorName:q.vendorName,vendorContact:q.vendorContact,vendorEmail:q.vendorEmail,poDate,deliveryDate,deliveryLocation:document.getElementById('po-location').value.trim(),items:(q.items||[]).map(i=>({...i,rate:i.quotedRate})),subtotal,shippingCharges:shipping,additionalDiscount:extraDiscount,total,status:'Draft',paymentTerms:q.paymentTerms||'',deliveryTime:q.deliveryTime||'',terms:document.getElementById('po-terms').value.trim(),createdAt:new Date().toISOString()});if(rfq)rfq.status='PO Created';recordActivity(x,'Created','Purchase Orders','Purchase order created: '+('PO-2026-'+String(next).padStart(3,'0')),'PO-2026-'+String(next).padStart(3,'0'));save(x);closeModal();renderOrders();toast('Purchase Order created successfully')}
function orderDetails(id){const x=db(),o=(x.orders||[]).find(a=>a.id===id);if(!o)return;openModal(`<div class="modal" id="modal"><div class="modal-box request-modal"><div class="modal-head"><div><h3>${esc(o.poNo)}</h3><small>${esc(o.vendorName)} — ${esc(o.rfqNo||'')}</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="detail-grid"><div><span>Vendor</span><b>${esc(o.vendorName)}</b></div><div><span>PO Date</span><b>${esc(o.poDate)}</b></div><div><span>Expected Delivery</span><b>${esc(o.deliveryDate)}</b></div><div><span>Status</span><b>${status(o.status)}</b></div><div><span>RFQ</span><b>${esc(o.rfqNo||'—')}</b></div><div><span>Quotation</span><b>${esc(o.quotationNo||'—')}</b></div><div><span>Payment Terms</span><b>${esc(o.paymentTerms||'—')}</b></div><div><span>Delivery Location</span><b>${esc(o.deliveryLocation||'—')}</b></div></div>${table(['Item','Qty','Unit','Rate','Tax','Discount','Total'],(o.items||[]).map(i=>`<tr><td>${esc(i.productName)}</td><td>${i.quantity}</td><td>${esc(i.unit||'')}</td><td>${money(i.rate||i.quotedRate)}</td><td>${Number(i.taxPercent||0)}%</td><td>${Number(i.discountPercent||0)}%</td><td><b>${money(i.total)}</b></td></tr>`).join(''))}<div class="po-totals"><div><span>Quotation Total</span><b>${money(o.subtotal)}</b></div><div><span>Shipping / Other</span><b>${money(o.shippingCharges)}</b></div><div><span>Additional Discount</span><b>${money(o.additionalDiscount)}</b></div><div class="grand"><span>PO Total</span><b>${money(o.total)}</b></div></div>${o.terms?`<div class="detail-note"><b>Terms & Conditions</b><p>${esc(o.terms)}</p></div>`:''}</div><div class="modal-foot"><button class="btn-secondary" onclick="downloadPOPdf(${o.id})"><i class="ti ti-file-type-pdf"></i> PDF</button><button class="btn-secondary" onclick="closeModal()">Close</button>${o.status==='Draft'?`<button class="btn-secondary" onclick="updatePOStatus(${o.id},'Cancelled')">Cancel PO</button><button class="btn-primary" onclick="updatePOStatus(${o.id},'Approved')"><i class="ti ti-check"></i> Approve PO</button>`:o.status==='Approved'?`<button class="btn-primary" onclick="updatePOStatus(${o.id},'Sent to Vendor')"><i class="ti ti-send"></i> Send to Vendor</button>`:''}</div></div></div>`)}
function updatePOStatus(id,newStatus){const x=db(),o=(x.orders||[]).find(a=>a.id===id);if(!o)return;o.status=newStatus;if(newStatus==='Approved')o.approvedAt=new Date().toISOString();if(newStatus==='Sent to Vendor')o.sentAt=new Date().toISOString();recordActivity(x,'Updated','Purchase Orders',o.poNo+' status changed to '+newStatus,o.poNo);save(x);closeModal();renderOrders();toast('Purchase Order '+newStatus.toLowerCase())}

function comparisonGroups(x){
 const map={};
 (x.quotations||[]).forEach(q=>{if(!q.rfqId)return;(map[q.rfqId]??=[]).push(q)});
 return Object.values(map).map(quotes=>({rfqId:quotes[0].rfqId,rfqNo:quotes[0].rfqNo,requestNo:quotes[0].requestNo,quotes:quotes.sort((a,b)=>Number(a.total||0)-Number(b.total||0))})).sort((a,b)=>String(b.rfqNo).localeCompare(String(a.rfqNo)));
}
function renderComparison(){
 need();const x=db(),groups=comparisonGroups(x),comparable=groups.filter(g=>g.quotes.length>=2),awarded=groups.filter(g=>g.quotes.some(q=>q.status==='Selected')).length;
 layout('comparison','Quotation Comparison','Compare vendor offers side-by-side and select the best quotation',`<div class="stats">${stat('RFQs with Quotes',groups.length,'ti-file-description')}${stat('Ready to Compare',comparable.length,'ti-scale')}${stat('Awarded',awarded,'ti-trophy')}${stat('Total Quotations',x.quotations.length,'ti-file-dollar')}</div><div class="section-card"><div class="section-head"><div><div class="section-title">Quotation Comparisons</div><div style="font-size:11px;color:#9CA3AF;margin-top:3px">Quotations are grouped by RFQ. Two or more responses are recommended for comparison.</div></div></div><div class="filters"><input id="comparison-search" placeholder="Search RFQ, request or vendor" oninput="filterComparisons()"><select id="comparison-filter" onchange="filterComparisons()"><option value="">All RFQs</option><option value="ready">Ready to Compare</option><option value="awarded">Awarded</option><option value="single">Single Quote</option></select></div><div id="comparison-list">${comparisonGroupCards(groups)}</div></div>`);
}
function comparisonGroupCards(groups){
 if(!groups.length)return `<div class="empty-state"><i class="ti ti-scale"></i><h3>No quotations to compare</h3><p>Record vendor quotations against an RFQ. They will appear here automatically.</p><a class="btn-primary inline-action" href="quotations.html"><i class="ti ti-plus"></i> Add Vendor Quotation</a></div>`;
 return `<div class="comparison-groups">${groups.map(g=>{const selected=g.quotes.find(q=>q.status==='Selected'),best=g.quotes[0];return `<div class="comparison-group" data-search="${esc((g.rfqNo+' '+g.requestNo+' '+g.quotes.map(q=>q.vendorName).join(' ')).toLowerCase())}" data-count="${g.quotes.length}" data-awarded="${selected?'1':'0'}"><div class="comparison-group-head"><div><div class="comparison-rfq">${esc(g.rfqNo||'RFQ')}</div><div class="comparison-meta">${esc(g.requestNo||'')} · ${g.quotes.length} quotation${g.quotes.length===1?'':'s'}</div></div><div class="comparison-head-actions">${selected?`<span class="award-chip"><i class="ti ti-trophy"></i> Awarded to ${esc(selected.vendorName)}</span>`:g.quotes.length>=2?`<span class="ready-chip">Ready to compare</span>`:`<span class="single-chip">Waiting for more quotes</span>`}<button class="btn-sm" onclick="openComparison('${g.rfqId}')"><i class="ti ti-scale"></i> Compare</button></div></div><div class="quote-summary-grid">${g.quotes.slice(0,4).map((q,i)=>`<div class="quote-summary ${q.status==='Selected'?'winner':''}"><div class="quote-vendor">${esc(q.vendorName)}</div><strong>${money(q.total)}</strong><small>${esc(q.deliveryTime||'Delivery not specified')} · ${esc(q.paymentTerms||'Terms not specified')}</small>${q.status==='Selected'?`<span class="mini-winner"><i class="ti ti-check"></i> Selected</span>`:i===0&&g.quotes.length>1&&!selected?`<span class="mini-lowest">Lowest total</span>`:''}</div>`).join('')}</div>${g.quotes.length>4?`<div class="more-quotes">+${g.quotes.length-4} more quotation(s)</div>`:''}</div>`}).join('')}</div>`;
}
function filterComparisons(){const x=db(),q=(document.getElementById('comparison-search')?.value||'').toLowerCase(),f=document.getElementById('comparison-filter')?.value||'';const groups=comparisonGroups(x).filter(g=>{const hay=(g.rfqNo+' '+g.requestNo+' '+g.quotes.map(a=>a.vendorName).join(' ')).toLowerCase(),awarded=g.quotes.some(a=>a.status==='Selected');return(!q||hay.includes(q))&&(!f||(f==='ready'&&g.quotes.length>=2&&!awarded)||(f==='awarded'&&awarded)||(f==='single'&&g.quotes.length===1))});document.getElementById('comparison-list').innerHTML=comparisonGroupCards(groups)}
function openComparison(rfqId){const x=db(),quotes=x.quotations.filter(q=>String(q.rfqId)===String(rfqId)).sort((a,b)=>Number(a.total||0)-Number(b.total||0));if(!quotes.length)return;const rfq=x.rfqs.find(r=>String(r.id)===String(rfqId)),selected=quotes.find(q=>q.status==='Selected'),items=(rfq?.items||quotes[0].items||[]);const lowest=Math.min(...quotes.map(q=>Number(q.total||0)));openModal(`<div class="modal" id="modal"><div class="modal-box comparison-modal"><div class="modal-head"><div><h3>Quotation Comparison — ${esc(quotes[0].rfqNo||'RFQ')}</h3><small>${esc(quotes[0].requestNo||'')} · Compare ${quotes.length} vendor offer${quotes.length===1?'':'s'}</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="comparison-scroll"><table class="comparison-table"><thead><tr><th class="criteria-col">Criteria</th>${quotes.map(q=>`<th class="vendor-col ${q.status==='Selected'?'selected-col':''}"><div class="vendor-heading"><span>${esc(q.vendorName)}</span><small>${esc(q.quotationNo)}</small>${q.status==='Selected'?`<b><i class="ti ti-trophy"></i> Selected</b>`:''}</div></th>`).join('')}</tr></thead><tbody><tr class="total-row"><td><b>Total Quotation</b></td>${quotes.map(q=>`<td class="${Number(q.total)===lowest&&quotes.length>1?'best-cell':''}"><strong>${money(q.total)}</strong>${Number(q.total)===lowest&&quotes.length>1?'<small>Lowest</small>':''}</td>`).join('')}</tr><tr><td>Delivery Time</td>${quotes.map(q=>`<td>${esc(q.deliveryTime||'—')}</td>`).join('')}</tr><tr><td>Payment Terms</td>${quotes.map(q=>`<td>${esc(q.paymentTerms||'—')}</td>`).join('')}</tr><tr><td>Valid Until</td>${quotes.map(q=>`<td>${esc(q.validUntil||'—')}</td>`).join('')}</tr><tr><td>Status</td>${quotes.map(q=>`<td>${status(q.status)}</td>`).join('')}</tr>${items.map((item,i)=>{const vals=quotes.map(q=>q.items?.[i]);const rates=vals.map(v=>Number(v?.quotedRate||Infinity)),minRate=Math.min(...rates);return `<tr class="item-separator"><td><b>${esc(item.productName||'Item '+(i+1))}</b><small>${item.quantity||vals[0]?.quantity||0} ${esc(item.unit||vals[0]?.unit||'')}</small></td>${vals.map(v=>`<td class="${Number(v?.quotedRate||Infinity)===minRate&&quotes.length>1?'best-cell':''}"><b>${money(v?.quotedRate||0)}</b><small>Tax ${Number(v?.taxPercent||0)}% · Disc. ${Number(v?.discountPercent||0)}%</small><span>${money(v?.total||0)} line total</span></td>`).join('')}</tr>`}).join('')}<tr><td>Notes</td>${quotes.map(q=>`<td class="notes-cell">${esc(q.notes||'—')}</td>`).join('')}</tr></tbody></table></div>${quotes.length<2?`<div class="comparison-warning"><i class="ti ti-alert-circle"></i><div><b>Only one quotation received</b><span>You can still review it, but a competitive comparison normally requires at least two vendor responses.</span></div></div>`:''}</div><div class="modal-foot comparison-foot"><button class="btn-secondary" onclick="closeModal()">Close</button>${!selected?quotes.map(q=>`<button class="btn-primary award-btn" onclick="awardQuotation(${q.id})"><i class="ti ti-trophy"></i> Select ${esc(q.vendorName)}</button>`).join(''):`<button class="btn-secondary" onclick="clearAward('${rfqId}')"><i class="ti ti-refresh"></i> Change Selection</button><button class="btn-primary" onclick="closeModal();location.href='orders.html'"><i class="ti ti-shopping-cart"></i> Create Purchase Order</button>`}</div></div></div>`)}
function awardQuotation(id){const x=db(),winner=x.quotations.find(q=>q.id===id);if(!winner)return;x.quotations.filter(q=>String(q.rfqId)===String(winner.rfqId)).forEach(q=>q.status=q.id===id?'Selected':'Rejected');const rfq=(x.rfqs||[]).find(r=>String(r.id)===String(winner.rfqId));if(rfq){rfq.status='Closed';rfq.completedAt=new Date().toISOString();}const existing=x.comparisons.find(c=>String(c.rfqId)===String(winner.rfqId));const record={id:existing?.id||Date.now(),rfqId:winner.rfqId,rfqNo:winner.rfqNo,requestNo:winner.requestNo,selectedQuotationId:winner.id,selectedQuotationNo:winner.quotationNo,vendorId:winner.vendorId,vendorName:winner.vendorName,total:winner.total,status:'Completed',comparedAt:new Date().toISOString()};if(existing)Object.assign(existing,record);else x.comparisons.unshift(record);recordActivity(x,'Selected','Quotation Comparison',winner.vendorName+' quotation selected for '+winner.rfqNo,winner.quotationNo);save(x);closeModal();renderComparison();toast(winner.vendorName+' quotation selected')}
function clearAward(rfqId){const x=db();x.quotations.filter(q=>String(q.rfqId)===String(rfqId)).forEach(q=>{if(q.status==='Selected'||q.status==='Rejected')q.status='Received'});const rfq=(x.rfqs||[]).find(r=>String(r.id)===String(rfqId));if(rfq){rfq.status='Response Received';delete rfq.completedAt;}x.comparisons=x.comparisons.filter(c=>String(c.rfqId)!==String(rfqId));recordActivity(x,'Cleared','Quotation Comparison','Quotation selection cleared for RFQ '+rfqId,rfqId);save(x);closeModal();renderComparison();toast('Selection cleared. You can choose another quotation.')}

function invoicePaidAmount(x,id){return (x.payments||[]).filter(p=>String(p.invoiceId)===String(id)&&p.status==='Processed').reduce((a,p)=>a+Number(p.amount||0),0)}
function invoiceBalance(x,i){return Math.max(0,Number(i.amount||0)-invoicePaidAmount(x,i.id))}
function paymentEligibleInvoices(x){return (x.invoices||[]).filter(i=>['Approved','Matched','Partially Paid'].includes(i.status)&&invoiceBalance(x,i)>0.01)}
function renderPayments(){need();const x=db(),ps=x.payments||[],is=x.invoices||[],paid=ps.filter(p=>p.status==='Processed').reduce((a,p)=>a+Number(p.amount||0),0),out=is.reduce((a,i)=>a+invoiceBalance(x,i),0),partial=is.filter(i=>{let p=invoicePaidAmount(x,i.id);return p>.01&&p<Number(i.amount||0)-.01}).length;layout('payments','Payments','Record and track vendor payments against approved invoices',`<div class="stats">${stat('Total Payments',ps.length,'ti-credit-card')}${stat('Paid Amount',money(paid),'ti-cash')}${stat('Outstanding',money(out),'ti-clock')}${stat('Partially Paid',partial,'ti-progress-check')}</div><div class="section-card"><div class="section-head"><div><div class="section-title">Vendor Payments</div><div style="font-size:11px;color:#9CA3AF;margin-top:3px">Full and partial payments with automatic invoice and PO completion</div></div><button class="btn-primary" onclick="openPayment()"><i class="ti ti-plus"></i> Record Payment</button></div><div class="filters"><input id="payment-search" placeholder="Search payment, invoice, PO or vendor" oninput="filterPayments()"><select id="payment-status" onchange="filterPayments()"><option value="">All Statuses</option><option>Processed</option><option>Cancelled</option></select></div><div id="payment-table">${paymentRows(ps)}</div></div>`)}
function paymentRows(rows){return table(['Payment No.','Invoice','PO No.','Vendor','Date','Amount','Method','Status','Actions'],rows.map(p=>`<tr><td><button class="link-btn" onclick="paymentDetails(${p.id})">${esc(p.paymentNo)}</button></td><td>${esc(p.invoiceNo||'—')}</td><td>${esc(p.poNo||'—')}</td><td>${esc(p.vendorName||'—')}</td><td>${esc(p.paymentDate||'—')}</td><td><b>${money(p.amount)}</b></td><td>${esc(p.method||'—')}</td><td>${status(p.status||'Processed')}</td><td><button class="btn-sm" onclick="paymentDetails(${p.id})"><i class="ti ti-eye"></i> View</button> <button class="btn-sm" onclick="downloadPaymentPdf(${p.id})"><i class="ti ti-file-type-pdf"></i> PDF</button></td></tr>`).join(''))}
function filterPayments(){const x=db(),q=(document.getElementById('payment-search')?.value||'').toLowerCase(),st=document.getElementById('payment-status')?.value||'';document.getElementById('payment-table').innerHTML=paymentRows((x.payments||[]).filter(p=>(!q||(p.paymentNo+' '+p.invoiceNo+' '+p.poNo+' '+p.vendorName).toLowerCase().includes(q))&&(!st||p.status===st)))}
function openPayment(){const x=db(),es=paymentEligibleInvoices(x);if(!es.length){toast('No approved invoices with an outstanding balance are available');return}openModal(`<div class="modal" id="modal"><div class="modal-box request-modal"><div class="modal-head"><div><h3>Record Vendor Payment</h3><small>Apply a full or partial payment to an approved invoice</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="grid2"><label>Vendor Invoice<select id="pay-invoice" onchange="loadPaymentInvoice()"><option value="">Select invoice</option>${es.map(i=>`<option value="${i.id}">${esc(i.invoiceNo)} — ${esc(i.vendorName)} — Balance ${money(invoiceBalance(x,i))}</option>`).join('')}</select></label><label>Payment Date<input id="pay-date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Payment Amount<input id="pay-amount" type="number" min="0.01" step="0.01" oninput="previewPayment()"></label><label>Payment Method<select id="pay-method"><option>Bank Transfer</option><option>Cheque</option><option>Cash</option><option>Online Transfer</option><option>Card</option></select></label><label>Reference No.<input id="pay-ref" placeholder="Transaction / cheque reference"></label><label>Bank / Account<input id="pay-account" placeholder="Optional account name"></label></div><div id="payment-preview"><div class="detail-note"><b>Select an invoice</b><p>Invoice total, paid amount and outstanding balance will appear here.</p></div></div><label>Notes<textarea id="pay-notes" rows="3" placeholder="Payment notes..."></textarea></div><div class="modal-foot"><button class="btn-secondary" onclick="closeModal()">Cancel</button><button class="btn-primary" onclick="savePayment()"><i class="ti ti-check"></i> Process Payment</button></div></div></div>`);loadPaymentInvoice()}
function loadPaymentInvoice(){const x=db(),i=x.invoices.find(a=>String(a.id)===String(document.getElementById('pay-invoice')?.value)),box=document.getElementById('payment-preview');if(!box)return;if(!i){box.innerHTML='<div class="detail-note"><b>Select an invoice</b><p>Invoice total, paid amount and outstanding balance will appear here.</p></div>';return}const p=invoicePaidAmount(x,i.id),b=invoiceBalance(x,i);document.getElementById('pay-amount').value=b.toFixed(2);box.innerHTML=`<div class="detail-grid"><div><span>Vendor</span><b>${esc(i.vendorName)}</b></div><div><span>Invoice</span><b>${esc(i.invoiceNo)}</b></div><div><span>PO</span><b>${esc(i.poNo||'—')}</b></div><div><span>Invoice Total</span><b>${money(i.amount)}</b></div><div><span>Already Paid</span><b>${money(p)}</b></div><div><span>Outstanding</span><b>${money(b)}</b></div></div><div id="payment-balance-preview" class="request-summary"><span>After Payment</span><strong></strong></div>`;previewPayment()}
function previewPayment(){const x=db(),i=x.invoices.find(a=>String(a.id)===String(document.getElementById('pay-invoice')?.value)),o=document.getElementById('payment-balance-preview');if(!i||!o)return;const b=invoiceBalance(x,i),a=Number(document.getElementById('pay-amount')?.value||0),r=Math.max(0,b-a);o.innerHTML=`<span>After Payment</span><strong class="${a>0&&a<=b+.01?'text-success':'text-danger'}">${a>0&&a<=b+.01?(r<=.01?'Invoice will be fully paid':'Remaining '+money(r)):'Enter a valid amount'}</strong>`}
function savePayment(){const x=db(),i=x.invoices.find(a=>String(a.id)===String(document.getElementById('pay-invoice')?.value));if(!i){toast('Select a vendor invoice');return}const b=invoiceBalance(x,i),a=Number(document.getElementById('pay-amount').value||0),d=document.getElementById('pay-date').value,m=document.getElementById('pay-method').value,r=document.getElementById('pay-ref').value.trim();if(!d||a<=0||a>b+.01){toast('Enter a valid payment amount within the outstanding balance');return}if(r&&(x.payments||[]).some(p=>String(p.referenceNo||'').toLowerCase()===r.toLowerCase())){toast('A payment with this reference already exists');return}const n=(x.payments||[]).length?Math.max(...x.payments.map(p=>Number(String(p.paymentNo||'').split('-').pop())||0))+1:1;x.payments=x.payments||[];x.payments.unshift({id:Date.now(),paymentNo:'PAY-2026-'+String(n).padStart(3,'0'),invoiceId:i.id,invoiceNo:i.invoiceNo,poId:i.poId,poNo:i.poNo,vendorId:i.vendorId,vendorName:i.vendorName,paymentDate:d,amount:a,method:m,referenceNo:r,account:document.getElementById('pay-account').value.trim(),notes:document.getElementById('pay-notes').value.trim(),status:'Processed',createdAt:new Date().toISOString()});const total=invoicePaidAmount(x,i.id),full=total>=Number(i.amount||0)-.01;i.status=full?'Paid':'Partially Paid';i.paidAmount=total;i.balance=invoiceBalance(x,i);if(full)i.paidAt=new Date().toISOString();const po=(x.orders||[]).find(o=>String(o.id)===String(i.poId));if(po&&full){po.status='Completed';po.completedAt=new Date().toISOString()}recordActivity(x,'Processed','Payments','Payment '+x.payments[0].paymentNo+' processed for '+money(a),x.payments[0].paymentNo);save(x);closeModal();renderPayments();toast(full?'Payment processed — invoice fully paid':'Payment processed — invoice remains partially paid')}
function paymentDetails(id){const x=db(),p=(x.payments||[]).find(a=>a.id===id),i=p&&(x.invoices||[]).find(a=>String(a.id)===String(p.invoiceId));if(!p)return;openModal(`<div class="modal" id="modal"><div class="modal-box request-modal"><div class="modal-head"><div><h3>${esc(p.paymentNo)}</h3><small>${esc(p.vendorName||'')} — ${esc(p.invoiceNo||'')}</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="detail-grid"><div><span>Payment No.</span><b>${esc(p.paymentNo)}</b></div><div><span>Invoice</span><b>${esc(p.invoiceNo||'—')}</b></div><div><span>PO</span><b>${esc(p.poNo||'—')}</b></div><div><span>Vendor</span><b>${esc(p.vendorName||'—')}</b></div><div><span>Payment Date</span><b>${esc(p.paymentDate||'—')}</b></div><div><span>Amount</span><b>${money(p.amount)}</b></div><div><span>Method</span><b>${esc(p.method||'—')}</b></div><div><span>Reference</span><b>${esc(p.referenceNo||'—')}</b></div><div><span>Invoice Total</span><b>${money(i?.amount||0)}</b></div><div><span>Outstanding</span><b>${money(i?invoiceBalance(x,i):0)}</b></div><div><span>Status</span><b>${status(p.status)}</b></div></div>${p.account?`<div class="detail-note"><b>Bank / Account</b><p>${esc(p.account)}</p></div>`:''}${p.notes?`<div class="detail-note"><b>Notes</b><p>${esc(p.notes)}</p></div>`:''}</div><div class="modal-foot"><button class="btn-secondary" onclick="downloadPaymentPdf(${p.id})"><i class="ti ti-file-type-pdf"></i> PDF</button><button class="btn-secondary" onclick="closeModal()">Close</button></div></div></div>`)}

function renderUsers(){if(!guard('users'))return;const x=db(),users=x.users||[],roles=Object.keys(x.roles||{});layout('users','User & Role Management','Manage users, roles and module permissions',`<div class="stats">${stat('Total Users',users.length,'ti-users')}${stat('Active Users',users.filter(u=>u.active!==false).length,'ti-user-check')}${stat('Roles',roles.length,'ti-shield-check')}${stat('Administrators',users.filter(u=>u.role==='Admin').length,'ti-shield') }</div><div class="section-card"><div class="section-head"><div><div class="section-title">System Users</div><div style="font-size:11px;color:#9CA3AF;margin-top:3px">Create users and assign procurement roles</div></div><button class="btn-primary" onclick="openUser()"><i class="ti ti-plus"></i> Add User</button></div>${table(['Name','Email','Role','Status','Actions'],users.map(u=>`<tr><td><b>${esc(u.name)}</b></td><td>${esc(u.email)}</td><td><span class="badge role-${String(u.role).toLowerCase().replaceAll(' ','-')}">${esc(u.role)}</span></td><td>${status(u.active===false?'Inactive':'Active')}</td><td><button class="btn-sm" onclick="openUser(${u.id})"><i class="ti ti-edit"></i> Edit</button> <button class="btn-sm" onclick="toggleUser(${u.id})">${u.active===false?'Activate':'Deactivate'}</button></td></tr>`).join(''))}</div><div class="section-card"><div class="section-head"><div><div class="section-title">Roles & Permissions</div><div style="font-size:11px;color:#9CA3AF;margin-top:3px">Control which modules each role can access</div></div></div>${roles.map(r=>roleCard(r,x.roles[r])).join('')}</div>`)}
function downloadQuotationPdf(id){const x=db(),q=(x.quotations||[]).find(a=>a.id===id);if(!q)return;if(!quotationPdfReady(x,q)){toast('Quotation PDF is available after the RFQ has been sent and the quotation is not rejected.');return}const c=(x.comparisons||[]).find(c=>String(c.rfqId)===String(q.rfqId)&&String(c.selectedQuotationId)===String(q.id));const rows=(q.items||[]).map(i=>[esc(i.productName),esc(i.quantity),esc(i.unit||'—'),money(i.quotedRate),`${Number(i.taxPercent||0)}%`,`${Number(i.discountPercent||0)}%`,money(i.total)]);downloadPDF(q.quotationNo,`<div class="grid">${pdfField('Quotation No.',q.quotationNo)}${pdfField('RFQ No.',q.rfqNo)}${pdfField('Purchase Request',q.requestNo)}${pdfField('Vendor',q.vendorName)}${pdfField('Quote Date',q.quoteDate)}${pdfField('Valid Until',q.validUntil)}${pdfField('Delivery',q.deliveryTime)}${pdfField('Payment Terms',q.paymentTerms)}${pdfField('Status',q.status)}</div><div class="section"><h3>Quoted Items</h3>${pdfTable(['Product','Qty','Unit','Rate','Tax','Discount','Total'],rows)}</div><div class="total">Quotation Total: ${money(q.total)}</div>${q.notes?`<div class="note"><b>Notes</b><br>${esc(q.notes)}</div>`:''}<div class="note"><b>Quotation Document</b><br>Generated from the vendor quotation for ${esc(q.rfqNo||'RFQ')}${c?.comparedAt?` and comparison completed on ${esc(new Date(c.comparedAt).toLocaleString())}.`:' for vendor sharing before quotation comparison.'}</div>`)}
function downloadRFQPDF(id){const x=db(),r=(x.rfqs||[]).find(a=>a.id===id);if(!r)return;const rows=(r.items||[]).map(i=>[esc(i.productName),esc(i.description||'—'),esc(i.quantity),esc(i.unit||'—'),money(i.rate),money(i.total)]);downloadPDF(r.rfqNo,`<div class="grid">${pdfField('RFQ No.',r.rfqNo)}${pdfField('Purchase Request',r.requestNo)}${pdfField('Issue Date',r.issueDate)}${pdfField('Due Date',r.dueDate)}${pdfField('Status',r.status)}${pdfField('Vendors',(r.vendors||[]).map(v=>v.name).join(', '))}</div><div class="section"><h3>Requested Items</h3>${pdfTable(['Product','Description','Qty','Unit','Estimated Rate','Total'],rows)}</div><div class="total">Estimated Total: ${money(r.estimatedTotal)}</div>${r.notes?`<div class="note"><b>Notes</b><br>${esc(r.notes)}</div>`:''}`)}
function downloadPOPdf(id){const x=db(),o=(x.orders||[]).find(a=>a.id===id);if(!o)return;const rows=(o.items||[]).map(i=>[esc(i.productName),esc(i.quantity),esc(i.unit||'—'),money(i.rate||i.quotedRate),`${Number(i.taxPercent||0)}%`,`${Number(i.discountPercent||0)}%`,money(i.total)]);downloadPDF(o.poNo,`<div class="grid">${pdfField('PO No.',o.poNo)}${pdfField('Vendor',o.vendorName)}${pdfField('PO Date',o.poDate)}${pdfField('Expected Delivery',o.deliveryDate)}${pdfField('RFQ',o.rfqNo)}${pdfField('Quotation',o.quotationNo)}${pdfField('Delivery Location',o.deliveryLocation)}${pdfField('Payment Terms',o.paymentTerms)}</div><div class="section"><h3>Order Items</h3>${pdfTable(['Item','Qty','Unit','Rate','Tax','Discount','Total'],rows)}</div><div class="grid">${pdfField('Quotation Total',money(o.subtotal))}${pdfField('Shipping / Other',money(o.shippingCharges))}${pdfField('Additional Discount',money(o.additionalDiscount))}${pdfField('Status',o.status)}</div><div class="total">PO Total: ${money(o.total)}</div>${o.terms?`<div class="note"><b>Terms & Conditions</b><br>${esc(o.terms)}</div>`:''}`)}
function downloadGRNPdf(id){const x=db(),r=(x.receipts||[]).find(a=>a.id===id);if(!r)return;const rows=(r.items||[]).map(i=>[esc(i.productName),esc(i.orderedQty),esc(i.receivedQty),esc(i.acceptedQty),esc(i.rejectedQty),esc(i.inspection||'—'),esc(i.remark||'—')]);downloadPDF(r.grnNo,`<div class="grid">${pdfField('GRN No.',r.grnNo)}${pdfField('PO No.',r.poNo)}${pdfField('Vendor',r.vendorName)}${pdfField('Receipt Date',r.receivedDate)}${pdfField('Location',r.location)}${pdfField('Received By',r.receivedBy)}${pdfField('Status',r.status)}</div><div class="section"><h3>Goods Received</h3>${pdfTable(['Item','Ordered','Received','Accepted','Rejected','Inspection','Remark'],rows)}</div>${r.notes?`<div class="note"><b>Inspection Notes</b><br>${esc(r.notes)}</div>`:''}`)}
function downloadInvoicePdf(id){const x=db(),i=(x.invoices||[]).find(a=>a.id===id);if(!i)return;const m=invoiceMatch(x,i);downloadPDF(i.invoiceNo,`<div class="grid">${pdfField('Invoice No.',i.invoiceNo)}${pdfField('Vendor',i.vendorName)}${pdfField('Invoice Date',i.invoiceDate)}${pdfField('Due Date',i.dueDate)}${pdfField('PO No.',i.poNo)}${pdfField('PO Total',money(m.po?.total||0))}${pdfField('Accepted GRN Value',money(m.received))}${pdfField('Invoice Amount',money(i.amount))}${pdfField('3-Way Match',i.matchStatus||m.status)}${pdfField('Status',i.status)}${pdfField('Reference',i.referenceNo)}</div>${i.notes?`<div class="note"><b>Notes</b><br>${esc(i.notes)}</div>`:''}<div class="total">Invoice Amount: ${money(i.amount)}</div>`)}
function downloadPaymentPdf(id){const x=db(),p=(x.payments||[]).find(a=>a.id===id);if(!p)return;const i=(x.invoices||[]).find(a=>String(a.id)===String(p.invoiceId));downloadPDF(p.paymentNo,`<div class="grid">${pdfField('Payment No.',p.paymentNo)}${pdfField('Invoice No.',p.invoiceNo)}${pdfField('PO No.',p.poNo)}${pdfField('Vendor',p.vendorName)}${pdfField('Payment Date',p.paymentDate)}${pdfField('Amount',money(p.amount))}${pdfField('Payment Method',p.method)}${pdfField('Reference No.',p.referenceNo)}${pdfField('Invoice Total',money(i?.amount||0))}${pdfField('Outstanding Balance',money(i?invoiceBalance(x,i):0))}${pdfField('Status',p.status)}</div>${p.account?`<div class="note"><b>Bank / Account</b><br>${esc(p.account)}</div>`:''}${p.notes?`<div class="note"><b>Notes</b><br>${esc(p.notes)}</div>`:''}<div class="total">Payment Amount: ${money(p.amount)}</div>`)}
function roleCard(role,perms){const labels={dashboard:'Dashboard',requests:'Purchase Requests',rfqs:'RFQs',quotations:'Vendor Quotations',comparison:'Quotation Comparison',orders:'Purchase Orders',receipts:'Goods Receipts',invoices:'Vendor Invoices',payments:'Payments',vendors:'Vendors',products:'Products',reports:'Reports',users:'User Management',activities:'Activities'};return `<div class="role-permission-card"><div><b>${esc(role)}</b><small>${Object.values(perms).filter(Boolean).length} modules enabled</small></div><button class="btn-sm" onclick="openRole('${esc(role)}')"><i class="ti ti-settings"></i> Permissions</button><div class="permission-chips">${Object.entries(labels).filter(([k])=>perms[k]).map(([,v])=>`<span>${esc(v)}</span>`).join('')}</div></div>`}
function openUser(id){const x=db(),u=id?(x.users||[]).find(a=>a.id===id):null,roles=Object.keys(x.roles||{});if(u?.role==='Admin'&&u.email==='admin@purchase.local'&&currentUser()?.email!==u.email){/* allowed to edit profile */}openModal(`<div class="modal" id="modal"><div class="modal-box request-modal"><div class="modal-head"><div><h3>${u?'Edit User':'Add User'}</h3><small>Create a login and assign a role</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="grid2"><label>Full Name<input id="user-name" value="${esc(u?.name||'')}"></label><label>Email Address<input id="user-email" type="email" value="${esc(u?.email||'')}"></label><label>Password<input id="user-password" type="password" placeholder="${u?'Leave blank to keep current password':'Set password'}"></label><label>Role<select id="user-role">${roles.map(r=>`<option ${u?.role===r?'selected':''}>${esc(r)}</option>`).join('')}</select></label></div><label class="check-line"><input id="user-active" type="checkbox" ${u?.active!==false?'checked':''}> Active user</label></div><div class="modal-foot"><button class="btn-secondary" onclick="closeModal()">Cancel</button><button class="btn-primary" onclick="saveUser(${u?.id||0})">Save User</button></div></div></div>`)}
function saveUser(id){const x=db(),name=document.getElementById('user-name').value.trim(),email=document.getElementById('user-email').value.trim().toLowerCase(),pw=document.getElementById('user-password').value,role=document.getElementById('user-role').value;if(!name||!email||(!id&&!pw)){toast('Name, email and password are required');return}if((x.users||[]).some(u=>u.email.toLowerCase()===email&&u.id!==id)){toast('A user with this email already exists');return}let u=(x.users||[]).find(a=>a.id===id);if(!u){u={id:Date.now(),name,email,password:pw,role,active:true};x.users.unshift(u)}else{u.name=name;u.email=email;u.role=role;u.active=document.getElementById('user-active').checked;if(pw)u.password=pw}if(!id)u.active=document.getElementById('user-active').checked;recordActivity(x,id?'Updated':'Created','Users',(id?'User updated: ':'User created: ')+name,'User');save(x);closeModal();renderUsers();toast(id?'User updated':'User created')}
function toggleUser(id){const x=db(),u=(x.users||[]).find(a=>a.id===id);if(!u)return;if(u.email==='admin@purchase.local'&&u.active!==false){toast('The main admin account cannot be deactivated');return}u.active=u.active===false;recordActivity(x,u.active?'Activated':'Deactivated','Users',u.name+' was '+(u.active?'activated':'deactivated'),'User');save(x);renderUsers();toast(u.active?'User activated':'User deactivated')}
function openRole(role){const x=db(),perms=x.roles[role],labels={dashboard:'Dashboard',requests:'Purchase Requests',rfqs:'RFQs',quotations:'Vendor Quotations',comparison:'Quotation Comparison',orders:'Purchase Orders',receipts:'Goods Receipts',invoices:'Vendor Invoices',payments:'Payments',vendors:'Vendors',products:'Products',reports:'Reports',users:'User Management',activities:'Activities'};openModal(`<div class="modal" id="modal"><div class="modal-box request-modal"><div class="modal-head"><div><h3>${esc(role)} Permissions</h3><small>Select the modules this role can access</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="permission-grid">${Object.entries(labels).map(([k,v])=>`<label class="permission-row"><input type="checkbox" data-perm="${k}" ${perms[k]?'checked':''}> <span>${esc(v)}</span></label>`).join('')}</div></div><div class="modal-foot"><button class="btn-secondary" onclick="closeModal()">Cancel</button><button class="btn-primary" onclick="saveRole('${esc(role)}')">Save Permissions</button></div></div></div>`)}
function saveRole(role){const x=db(),p=x.roles[role]||{};document.querySelectorAll('[data-perm]').forEach(el=>p[el.dataset.perm]=el.checked);x.roles[role]=p;recordActivity(x,'Updated','Roles','Permissions updated for role: '+role,'Role');save(x);closeModal();renderUsers();toast('Permissions updated for '+role)}
